#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum ObjectPlacementMode {
    PreferPrimary,
    PreferHighSpeed,
    BalanceHighSpeed,
}

impl ObjectPlacementMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::PreferPrimary => "prefer_primary",
            Self::PreferHighSpeed => "prefer_high_speed",
            Self::BalanceHighSpeed => "balance_high_speed",
        }
    }
}

fn default_object_placement_mode() -> ObjectPlacementMode {
    match env::var("CCBG_OBJECT_PLACEMENT_MODE")
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "prefer_high_speed" => ObjectPlacementMode::PreferHighSpeed,
        "balance_high_speed" => ObjectPlacementMode::BalanceHighSpeed,
        _ => ObjectPlacementMode::PreferPrimary,
    }
}

