#[derive(Debug, Clone, Copy)]
struct ReplicationRetryPolicy {
    max_attempts: u32,
    base_delay_ms: u64,
    max_delay_ms: u64,
}

impl ReplicationRetryPolicy {
    fn delay_for_attempt(self, attempts: u32) -> u64 {
        if self.base_delay_ms == 0 {
            return 0;
        }

        let shift = attempts.saturating_sub(1).min(20);
        let multiplier = 1_u64 << shift;
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms.max(self.base_delay_ms))
    }
}

impl AdminMode {
    fn parse(raw: &str) -> Result<Self> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "" | "web" => Ok(Self::Web),
            "terminal" | "tui" => Ok(Self::Terminal),
            "off" | "disabled" | "none" => Ok(Self::Off),
            other => anyhow::bail!("unsupported CCBG_ADMIN_MODE: {other}"),
        }
    }
}

impl AuthBrokerState {
    fn new() -> Self {
        Self {
            http_client: HttpClient::new(),
            pending_pkce: Arc::new(Mutex::new(HashMap::new())),
            device_flows: Arc::new(Mutex::new(HashMap::new())),
            capture_prompts: Arc::new(Mutex::new(HashMap::new())),
            browser_flow_sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }
}

impl OnedriveScopeMode {
    fn parse(raw: &str) -> Self {
        match raw.trim().to_ascii_lowercase().as_str() {
            "selected" | "selected_only" | "important_only" => Self::SelectedOnly,
            "memory" | "memory_only" | "agent_memory" => Self::MemoryOnly,
            _ => Self::All,
        }
    }
}

impl OnedrivePolicy {
    fn from_env_defaults(topology: &TopologyPolicy) -> Self {
        let selected_buckets =
            normalize_bucket_list(&env_csv_list("CCBG_ONEDRIVE_SELECTED_BUCKETS"));
        let selected_prefixes =
            normalize_prefix_list(&env_csv_list("CCBG_ONEDRIVE_SELECTED_PREFIXES"));
        let memory_buckets = normalize_bucket_list(&env_csv_list("CCBG_ONEDRIVE_MEMORY_BUCKETS"));
        let memory_prefixes = normalize_prefix_list(&env_csv_list("CCBG_ONEDRIVE_MEMORY_PREFIXES"));
        Self {
            replication_enabled: env_bool(
                "CCBG_ONEDRIVE_REPLICATION_ENABLED",
                topology.sync_targets.contains(&ProviderId::Onedrive),
            ),
            scope_mode: OnedriveScopeMode::parse(&env_or("CCBG_ONEDRIVE_POLICY_MODE", "all")),
            selected_buckets: if selected_buckets.is_empty() {
                memory_buckets.clone()
            } else {
                selected_buckets
            },
            selected_prefixes: if selected_prefixes.is_empty() {
                memory_prefixes.clone()
            } else {
                selected_prefixes
            },
            memory_buckets,
            memory_prefixes,
            updated_at_unix_ms: current_unix_ms(),
        }
    }

    fn from_input(input: OnedrivePolicyInput) -> Self {
        let selected_buckets = normalize_bucket_list(&input.selected_buckets);
        let selected_prefixes = normalize_prefix_list(&input.selected_prefixes);
        let memory_buckets = normalize_bucket_list(&input.memory_buckets);
        let memory_prefixes = normalize_prefix_list(&input.memory_prefixes);
        Self {
            replication_enabled: input.replication_enabled,
            scope_mode: input.scope_mode,
            selected_buckets: if selected_buckets.is_empty() {
                memory_buckets.clone()
            } else {
                selected_buckets
            },
            selected_prefixes: if selected_prefixes.is_empty() {
                memory_prefixes.clone()
            } else {
                selected_prefixes
            },
            memory_buckets,
            memory_prefixes,
            updated_at_unix_ms: current_unix_ms(),
        }
    }

    fn matches_bucket(&self, bucket: &str) -> bool {
        match self.scope_mode {
            OnedriveScopeMode::All => true,
            OnedriveScopeMode::SelectedOnly => {
                if self.selected_buckets.iter().any(|value| value == bucket) {
                    true
                } else {
                    !self.selected_prefixes.is_empty()
                }
            }
            OnedriveScopeMode::MemoryOnly => {
                if self.memory_buckets.iter().any(|value| value == bucket) {
                    true
                } else {
                    !self.memory_prefixes.is_empty()
                }
            }
        }
    }

    fn matches_object(&self, bucket: &str, key: &str) -> bool {
        match self.scope_mode {
            OnedriveScopeMode::All => true,
            OnedriveScopeMode::SelectedOnly => {
                self.selected_buckets.iter().any(|value| value == bucket)
                    || self
                        .selected_prefixes
                        .iter()
                        .any(|prefix| key.starts_with(prefix))
            }
            OnedriveScopeMode::MemoryOnly => {
                self.memory_buckets.iter().any(|value| value == bucket)
                    || self
                        .memory_prefixes
                        .iter()
                        .any(|prefix| key.starts_with(prefix))
            }
        }
    }
}

impl SmbSidecarConfig {
    fn from_env_defaults() -> Self {
        Self {
            enabled: env_bool("CCBG_SMB_ENABLED", false),
            bind_addr: env_or("CCBG_SMB_BIND_ADDR", &default_smb_bind_addr()),
            port: env_u16("CCBG_SMB_PORT", default_smb_port()),
            sidecar_image: env_or("CCBG_SMB_SIDECAR_IMAGE", &default_smb_sidecar_image()),
            rclone_image: env_or("CCBG_SMB_RCLONE_IMAGE", &default_smb_rclone_image()),
            mount_root: env_or("CCBG_SMB_MOUNT_ROOT", &default_smb_mount_root()),
            config_root: env_or("CCBG_SMB_CONFIG_ROOT", &default_smb_config_root()),
            data_root: env_or("CCBG_SMB_DATA_ROOT", &default_smb_data_root()),
            workgroup: env_or("CCBG_SMB_WORKGROUP", &default_smb_workgroup()),
            server_string: env_opt("CCBG_SMB_SERVER_STRING"),
            create_mask: env_or("CCBG_SMB_CREATE_MASK", &default_smb_global_create_mask()),
            directory_mask: env_or(
                "CCBG_SMB_DIRECTORY_MASK",
                &default_smb_global_directory_mask(),
            ),
            disable_splice: env_bool("CCBG_SMB_DISABLE_SPLICE", false),
            macos_compatible: env_bool("CCBG_SMB_MACOS_COMPATIBLE", true),
            vfs_objects: normalize_string_list(&env_csv_list("CCBG_SMB_VFS_OBJECTS")),
            users: Vec::new(),
            shares: Vec::new(),
            updated_at_unix_ms: current_unix_ms(),
        }
        .normalize()
    }

    fn normalize(mut self) -> Self {
        self.bind_addr = normalize_required_text(self.bind_addr, default_smb_bind_addr());
        self.port = normalize_smb_port(self.port);
        self.sidecar_image =
            normalize_required_text(self.sidecar_image, default_smb_sidecar_image());
        self.rclone_image = normalize_required_text(self.rclone_image, default_smb_rclone_image());
        self.mount_root = normalize_required_text(self.mount_root, default_smb_mount_root());
        self.config_root = normalize_required_text(self.config_root, default_smb_config_root());
        self.data_root = normalize_required_text(self.data_root, default_smb_data_root());
        self.workgroup = normalize_smb_workgroup(self.workgroup);
        self.server_string = normalize_secret_field(self.server_string);
        self.create_mask = normalize_smb_mask(self.create_mask, default_smb_global_create_mask());
        self.directory_mask =
            normalize_smb_mask(self.directory_mask, default_smb_global_directory_mask());
        let vfs_objects = if self.vfs_objects.is_empty() {
            default_smb_vfs_objects()
        } else {
            self.vfs_objects.clone()
        };
        self.vfs_objects = normalize_string_list(&vfs_objects);
        self
    }
}

impl AuthCapturePolicy {
    fn from_env_defaults() -> Self {
        let cdp_endpoint_url = env_opt("CCBG_AUTH_CAPTURE_CDP_ENDPOINT_URL");
        let cdp_target_selector = env_opt("CCBG_AUTH_CAPTURE_CDP_TARGET_SELECTOR");
        let cdp_target_timeout_ms = env_opt("CCBG_AUTH_CAPTURE_CDP_TARGET_TIMEOUT_MS")
            .and_then(|value| value.parse::<u64>().ok());
        let llm_endpoint = env_opt("CCBG_AUTH_CAPTURE_LLM_ENDPOINT");
        let llm_model_id = env_opt("CCBG_AUTH_CAPTURE_LLM_MODEL_ID");
        let llm_api_key = env_opt_or_file(
            "CCBG_AUTH_CAPTURE_LLM_API_KEY",
            "CCBG_AUTH_CAPTURE_LLM_API_KEY_FILE",
        );
        let browser_endpoints = auth_capture_browser_endpoints_from_legacy_fields(
            cdp_endpoint_url.clone(),
            cdp_target_selector.clone(),
            cdp_target_timeout_ms,
        );
        let llm_endpoints = auth_capture_llm_endpoints_from_legacy_fields(
            llm_endpoint.clone(),
            llm_model_id.clone(),
            llm_api_key.clone(),
        );
        Self {
            enabled: env_bool("CCBG_AUTH_CAPTURE_ENABLED", false),
            broker_url: env_opt("CCBG_AUTH_CAPTURE_BROKER_URL"),
            browser_endpoints,
            cdp_endpoint_url,
            cdp_target_selector,
            cdp_target_timeout_ms,
            llm_analysis_enabled: env_bool("CCBG_AUTH_CAPTURE_LLM_ANALYSIS_ENABLED", false),
            llm_endpoints,
            llm_endpoint,
            llm_model_id,
            llm_api_key,
            updated_at_unix_ms: current_unix_ms(),
        }
    }

    fn apply_input(&mut self, input: AuthCapturePolicyInput) {
        self.enabled = input.enabled;
        self.broker_url = normalize_secret_field(input.broker_url);
        self.browser_endpoints = auth_capture_browser_endpoints_from_input(
            input.browser_endpoints,
            input.cdp_endpoint_url.clone(),
            input.cdp_target_selector.clone(),
            input.cdp_target_timeout_ms,
            &self.browser_endpoints,
        );
        let legacy_endpoint = self.browser_endpoints.first().cloned().or_else(|| {
            auth_capture_browser_endpoint_from_legacy_fields(
                input.cdp_endpoint_url.clone(),
                input.cdp_target_selector.clone(),
                input.cdp_target_timeout_ms,
            )
        });
        self.cdp_endpoint_url = legacy_endpoint
            .as_ref()
            .map(|entry| entry.endpoint_url.clone());
        self.cdp_target_selector = legacy_endpoint.and_then(|entry| entry.target_selector);
        self.cdp_target_timeout_ms = self
            .browser_endpoints
            .first()
            .and_then(|entry| entry.target_timeout_ms)
            .or(input.cdp_target_timeout_ms.filter(|value| *value > 0));
        self.llm_analysis_enabled = input.llm_analysis_enabled;
        self.llm_endpoints = auth_capture_llm_endpoints_from_input(
            input.llm_endpoints,
            &self.llm_endpoints,
            input.llm_endpoint.clone(),
            input.llm_model_id.clone(),
            if input.clear_llm_api_key {
                None
            } else {
                input.llm_api_key.clone()
            },
        );
        let legacy_llm = self.llm_endpoints.first().cloned().or_else(|| {
            auth_capture_llm_endpoint_from_legacy_fields(
                input.llm_endpoint.clone(),
                input.llm_model_id.clone(),
                if input.clear_llm_api_key {
                    None
                } else {
                    input.llm_api_key.clone()
                },
            )
        });
        self.llm_endpoint = legacy_llm.as_ref().map(|entry| entry.endpoint_url.clone());
        self.llm_model_id = legacy_llm.as_ref().map(|entry| entry.model_id.clone());
        self.llm_api_key = legacy_llm.and_then(|entry| entry.api_key);
        self.updated_at_unix_ms = current_unix_ms();
    }

    fn payload(&self) -> AuthCapturePolicyPayload {
        let legacy_endpoint = self.browser_endpoints.first().cloned().or_else(|| {
            auth_capture_browser_endpoint_from_legacy_fields(
                self.cdp_endpoint_url.clone(),
                self.cdp_target_selector.clone(),
                self.cdp_target_timeout_ms,
            )
        });
        AuthCapturePolicyPayload {
            enabled: self.enabled,
            broker_url: self.broker_url.clone(),
            browser_endpoints: self.browser_endpoints.clone(),
            cdp_endpoint_url: legacy_endpoint
                .as_ref()
                .map(|entry| entry.endpoint_url.clone()),
            cdp_target_selector: legacy_endpoint.and_then(|entry| entry.target_selector),
            cdp_target_timeout_ms: self
                .browser_endpoints
                .first()
                .and_then(|entry| entry.target_timeout_ms)
                .or(self.cdp_target_timeout_ms),
            llm_analysis_enabled: self.llm_analysis_enabled,
            llm_endpoints: self
                .llm_endpoints
                .iter()
                .map(auth_capture_llm_endpoint_payload)
                .collect(),
            llm_endpoint: self
                .llm_endpoints
                .first()
                .map(|entry| entry.endpoint_url.clone())
                .or(self.llm_endpoint.clone()),
            llm_model_id: self
                .llm_endpoints
                .first()
                .map(|entry| entry.model_id.clone())
                .or(self.llm_model_id.clone()),
            llm_api_key_present: self
                .llm_endpoints
                .first()
                .and_then(|entry| entry.api_key.as_deref())
                .or(self.llm_api_key.as_deref())
                .as_deref()
                .map(str::trim)
                .is_some_and(|value| !value.is_empty()),
            updated_at_unix_ms: self.updated_at_unix_ms,
        }
    }
}

impl AuthCapturePrompt {
    fn from_input(input: AuthCapturePromptCreateInput) -> Self {
        Self {
            prompt_id: random_urlsafe_token(16),
            provider: input.provider.trim().to_string(),
            session_id: normalize_secret_field(input.session_id),
            flow_id: normalize_secret_field(input.flow_id),
            input_id: normalize_secret_field(input.input_id),
            title: input.title.trim().to_string(),
            message: input.message.trim().to_string(),
            field_label: input.field_label.trim().to_string(),
            field_kind: input.field_kind,
            placeholder: normalize_secret_field(input.placeholder),
            status: "pending".to_string(),
            created_at_unix_ms: current_unix_ms(),
            answered_at_unix_ms: None,
            answer_present: false,
            answer_value: None,
        }
    }

    fn answer(&mut self, value: String) {
        self.answer_value = Some(value);
        self.answer_present = true;
        self.status = "answered".to_string();
        self.answered_at_unix_ms = Some(current_unix_ms());
    }

    fn sanitized(&self) -> Self {
        let mut copy = self.clone();
        copy.answer_value = None;
        copy
    }
}

impl BrowserFlowAuthSession {
    fn new(
        session_id: String,
        provider: String,
        surface: String,
        flow_id: String,
        inputs: BTreeMap<String, serde_json::Value>,
        runtime: BTreeMap<String, serde_json::Value>,
    ) -> Self {
        let now = current_unix_ms();
        Self {
            session_id,
            provider,
            surface,
            flow_id,
            status: BROWSER_FLOW_AUTH_SESSION_STATUS_PENDING.to_string(),
            inputs,
            runtime,
            created_at_unix_ms: now,
            updated_at_unix_ms: now,
            report: None,
            last_error: None,
            cdp_endpoint_url: None,
            cdp_target_selector: None,
            cdp_target_timeout_ms: None,
            manual_challenge: None,
        }
    }

    fn apply_request(
        &mut self,
        provider: String,
        surface: String,
        flow_id: String,
        inputs: BTreeMap<String, serde_json::Value>,
        runtime: BTreeMap<String, serde_json::Value>,
    ) {
        self.provider = provider;
        self.surface = surface;
        self.flow_id = flow_id;
        self.inputs.extend(inputs);
        self.runtime.extend(runtime);
        self.updated_at_unix_ms = current_unix_ms();
        if matches!(
            self.status.as_str(),
            BROWSER_FLOW_AUTH_SESSION_STATUS_COMPLETED | BROWSER_FLOW_AUTH_SESSION_STATUS_FAILED
        ) {
            self.status = BROWSER_FLOW_AUTH_SESSION_STATUS_PENDING.to_string();
            self.report = None;
            self.last_error = None;
        }
        self.manual_challenge = None;
    }

    fn set_status(&mut self, status: &str) {
        self.status = status.to_string();
        self.updated_at_unix_ms = current_unix_ms();
    }

    fn set_completed(&mut self, report: BrowserFlowExecutionReport) {
        self.status = BROWSER_FLOW_AUTH_SESSION_STATUS_COMPLETED.to_string();
        self.report = Some(report);
        self.last_error = None;
        self.manual_challenge = None;
        self.updated_at_unix_ms = current_unix_ms();
    }

    fn set_failed(&mut self, error: &BlobError) {
        self.status = BROWSER_FLOW_AUTH_SESSION_STATUS_FAILED.to_string();
        self.last_error = Some(error.to_string());
        self.updated_at_unix_ms = current_unix_ms();
    }
}

impl GatewayBrowserFlowSession {
    fn new(
        inner: CdpBrowserFlowSession,
        http_client: HttpClient,
        auth_capture_policy: AuthCapturePolicy,
    ) -> Self {
        Self {
            inner,
            http_client,
            auth_capture_policy,
        }
    }

    async fn wait_for_visual_captcha_elements(
        &self,
        request: &BrowserFlowVisualCaptchaRequest,
        timeout: Duration,
    ) -> Result<(bool, bool), BlobError> {
        let deadline = tokio::time::Instant::now() + timeout;
        loop {
            let input_present = self.inner.element_exists(&request.input_element).await?;
            let image_present = self.inner.element_exists(&request.image_element).await?;
            if input_present && image_present {
                return Ok((input_present, image_present));
            }
            if tokio::time::Instant::now() >= deadline {
                return Ok((input_present, image_present));
            }
            sleep(Duration::from_millis(200)).await;
        }
    }

    async fn solve_visual_captcha_with_llm(
        &self,
        request: &BrowserFlowVisualCaptchaRequest,
    ) -> Result<String, BlobError> {
        let endpoints = enabled_auth_capture_llm_endpoints(&self.auth_capture_policy);
        if !self.auth_capture_policy.llm_analysis_enabled {
            warn!(
                input_id = %request.input_id,
                image_element = %request.image_element.id,
                "visual captcha solver skipped because LLM analysis is disabled"
            );
            return Err(interactive_captcha_input_required(
                request,
                Some(
                    "No multimodal LLM is enabled for auth assistance. Enter the captcha manually or enable a vision-capable model in the LLM tab."
                        .to_string(),
                ),
            ));
        }
        if endpoints.is_empty() {
            warn!(
                input_id = %request.input_id,
                image_element = %request.image_element.id,
                "visual captcha solver skipped because no enabled LLM endpoints are configured"
            );
            return Err(interactive_captcha_input_required(
                request,
                Some(
                    "No enabled LLM endpoint is configured for auth assistance. Enter the captcha manually or add a vision-capable endpoint in the LLM tab."
                        .to_string(),
                ),
            ));
        }
        let mut image_present = self.inner.element_exists(&request.image_element).await?;
        let mut input_present = self.inner.element_exists(&request.input_element).await?;
        if !image_present || !input_present {
            let wait_timeout = if request.optional {
                Duration::from_millis(2500)
            } else {
                Duration::from_secs(12)
            };
            if request.optional {
                info!(
                    input_id = %request.input_id,
                    image_element = %request.image_element.id,
                    input_element = %request.input_element.id,
                    input_present,
                    image_present,
                    wait_ms = wait_timeout.as_millis() as u64,
                    "waiting briefly for optional visual captcha row to appear"
                );
            } else {
                warn!(
                    input_id = %request.input_id,
                    image_element = %request.image_element.id,
                    input_element = %request.input_element.id,
                    input_present,
                    image_present,
                    wait_ms = wait_timeout.as_millis() as u64,
                    "waiting for visual captcha row to appear"
                );
            }
            let (resolved_input_present, resolved_image_present) = self
                .wait_for_visual_captcha_elements(request, wait_timeout)
                .await?;
            input_present = resolved_input_present;
            image_present = resolved_image_present;
        }
        if !image_present {
            if request.optional {
                info!(
                    input_id = %request.input_id,
                    image_element = %request.image_element.id,
                    input_element = %request.input_element.id,
                    input_present,
                    "optional visual captcha image element did not appear; skipping solve"
                );
            } else {
                warn!(
                    input_id = %request.input_id,
                    image_element = %request.image_element.id,
                    input_element = %request.input_element.id,
                    input_present,
                    "visual captcha image element did not resolve before LLM solve"
                );
            }
            return Err(BlobError::NotFound(format!(
                "visual captcha image element not found: {}",
                request.image_element.id
            )));
        }

        let max_attempts = request.max_attempts.unwrap_or(1).max(1);
        let mut failures = Vec::new();
        for attempt in 0..max_attempts {
            if attempt > 0 {
                if let Some(refresh_element) = request.refresh_element.as_ref() {
                    self.inner.click(refresh_element).await?;
                    self.inner.wait(600).await?;
                }
                if !self.inner.element_exists(&request.image_element).await? {
                    return Err(BlobError::NotFound(format!(
                        "visual captcha image element disappeared: {}",
                        request.image_element.id
                    )));
                }
            }

            let screenshot = self
                .inner
                .capture_element_screenshot_png_base64(&request.image_element)
                .await?;
            info!(
                input_id = %request.input_id,
                image_element = %request.image_element.id,
                attempt = attempt + 1,
                endpoint_count = endpoints.len(),
                "attempting multimodal captcha solve"
            );
            for endpoint in &endpoints {
                match request_visual_captcha_answer(
                    &self.http_client,
                    endpoint,
                    request,
                    &screenshot,
                )
                .await
                {
                    Ok(answer) => {
                        info!(
                            input_id = %request.input_id,
                            image_element = %request.image_element.id,
                            endpoint = %auth_capture_llm_endpoint_display_name(endpoint),
                            attempt = attempt + 1,
                            "multimodal captcha solve succeeded"
                        );
                        return Ok(answer);
                    }
                    Err(error) => failures.push(format!(
                        "{} attempt {}: {}",
                        auth_capture_llm_endpoint_display_name(endpoint),
                        attempt + 1,
                        error
                    )),
                }
            }
        }

        Err(interactive_captcha_input_required(
            request,
            Some(format!(
                "Automatic captcha solving did not return a usable answer. Enter the captcha manually, then resume the flow. {}",
                summarize_captcha_failures(&failures)
            )),
        ))
    }

    async fn validate_visual_layout_with_llm(
        &self,
        request: &BrowserFlowVisualLayoutValidationRequest,
    ) -> Result<(), BlobError> {
        let endpoints = enabled_auth_capture_llm_endpoints(&self.auth_capture_policy);
        if !self.auth_capture_policy.llm_analysis_enabled {
            return Err(BlobError::NotImplemented(
                "visual layout validation requires a multimodal LLM, but LLM analysis is disabled"
                    .to_string(),
            ));
        }
        if endpoints.is_empty() {
            return Err(BlobError::NotImplemented(
                "visual layout validation requires at least one enabled multimodal LLM endpoint"
                    .to_string(),
            ));
        }

        let page_context = self
            .inner
            .evaluate_value(
                "(() => ({ title: document.title || '', url: location.href, viewport: { width: window.innerWidth || 0, height: window.innerHeight || 0 } }))()",
            )
            .await?;
        let screenshot = self.inner.capture_viewport_screenshot_png_base64().await?;
        let mut candidates = Vec::with_capacity(request.targets.len());
        for target in &request.targets {
            let snapshot = self.inner.inspect_element_snapshot(&target.element).await?;
            candidates.push(VisualLayoutValidationCandidatePayload {
                element_id: target.element.id.clone(),
                role: target.role.clone(),
                required: target.required,
                dom_found: snapshot.is_some(),
                snapshot,
            });
        }

        info!(
            target_count = candidates.len(),
            "attempting multimodal visual layout validation"
        );
        let mut failures = Vec::new();
        for endpoint in &endpoints {
            match request_visual_layout_validation(
                &self.http_client,
                endpoint,
                request,
                &page_context,
                &candidates,
                &screenshot,
            )
            .await
            {
                Ok(result) if result.ok => {
                    let validated_roles = result.validated_roles.join(",");
                    info!(
                        endpoint = %auth_capture_llm_endpoint_display_name(endpoint),
                        target_count = candidates.len(),
                        validated_roles = %validated_roles,
                        "multimodal visual layout validation succeeded"
                    );
                    return Ok(());
                }
                Ok(result) => {
                    let summary = result
                        .summary
                        .as_deref()
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                        .unwrap_or("visual layout validation reported a mismatch");
                    let issues = if result.issues.is_empty() {
                        String::new()
                    } else {
                        format!(" issues={}", result.issues.join(" | "))
                    };
                    let validated_roles = if result.validated_roles.is_empty() {
                        String::new()
                    } else {
                        format!(" validated_roles={}", result.validated_roles.join(","))
                    };
                    warn!(
                        endpoint = %auth_capture_llm_endpoint_display_name(endpoint),
                        target_count = candidates.len(),
                        summary = %summary,
                        validated_roles = %result.validated_roles.join(","),
                        "multimodal visual layout validation detected a mismatch"
                    );
                    return Err(BlobError::Upstream(format!(
                        "{summary}{issues}{validated_roles}"
                    )));
                }
                Err(error) => failures.push(format!(
                    "{}: {}",
                    auth_capture_llm_endpoint_display_name(endpoint),
                    error
                )),
            }
        }

        Err(BlobError::NotImplemented(format!(
            "visual layout validation could not get a usable response from any multimodal LLM endpoint: {}",
            failures.join(" | ")
        )))
    }
}

#[async_trait::async_trait]
impl BrowserFlowSession for GatewayBrowserFlowSession {
    async fn navigate(&self, url: &str) -> Result<(), BlobError> {
        self.inner.navigate(url).await
    }

    async fn click(&self, element: &blob_core::BrowserFlowElement) -> Result<(), BlobError> {
        self.inner.click(element).await
    }

    async fn set_input(
        &self,
        element: &blob_core::BrowserFlowElement,
        value: &str,
        dispatch_events: &[String],
    ) -> Result<(), BlobError> {
        self.inner.set_input(element, value, dispatch_events).await
    }

    async fn invoke_operation(
        &self,
        operation: &blob_core::BrowserFlowOperation,
    ) -> Result<(), BlobError> {
        self.inner.invoke_operation(operation).await
    }

    async fn set_files(
        &self,
        element: &blob_core::BrowserFlowElement,
        paths: &[String],
    ) -> Result<(), BlobError> {
        self.inner.set_files(element, paths).await
    }

    async fn dispatch_events(
        &self,
        element: &blob_core::BrowserFlowElement,
        events: &[String],
    ) -> Result<(), BlobError> {
        self.inner.dispatch_events(element, events).await
    }

    async fn validate_visual_layout(
        &self,
        request: &BrowserFlowVisualLayoutValidationRequest,
    ) -> Result<(), BlobError> {
        self.validate_visual_layout_with_llm(request).await
    }

    async fn solve_visual_captcha(
        &self,
        request: &BrowserFlowVisualCaptchaRequest,
    ) -> Result<(), BlobError> {
        if let Some(value) = request.manual_value.as_deref() {
            warn!(
                input_id = %request.input_id,
                input_element = %request.input_element.id,
                source = "manual",
                value_length = value.chars().count(),
                "writing visual captcha value into page input"
            );
            return self
                .inner
                .set_input(&request.input_element, value, &request.dispatch_events)
                .await;
        }
        let answer = self.solve_visual_captcha_with_llm(request).await?;
        warn!(
            input_id = %request.input_id,
            input_element = %request.input_element.id,
            source = "llm",
            value_length = answer.chars().count(),
            "writing visual captcha value into page input"
        );
        self.inner
            .set_input(&request.input_element, &answer, &request.dispatch_events)
            .await
    }

    async fn wait_for_request(
        &self,
        request: &blob_core::BrowserFlowRequest,
        timeout_ms: Option<u64>,
    ) -> Result<(), BlobError> {
        self.inner.wait_for_request(request, timeout_ms).await
    }

    async fn wait_for_page(
        &self,
        page: &blob_core::BrowserFlowPage,
        timeout_ms: Option<u64>,
    ) -> Result<(), BlobError> {
        self.inner.wait_for_page(page, timeout_ms).await
    }

    async fn wait(&self, duration_ms: u64) -> Result<(), BlobError> {
        self.inner.wait(duration_ms).await
    }
}

#[async_trait::async_trait]
impl BrowserFlowOutputReader for GatewayBrowserFlowSession {
    async fn evaluate_output_script(
        &self,
        expression: &str,
        frame_selector: Option<&str>,
    ) -> Result<serde_json::Value, BlobError> {
        self.inner
            .evaluate_value_in_frame(expression, frame_selector)
            .await
    }

    async fn read_dom_text(
        &self,
        expression: &str,
        frame_selector: Option<&str>,
    ) -> Result<Option<String>, BlobError> {
        match self
            .inner
            .evaluate_value_in_frame(expression, frame_selector)
            .await?
        {
            serde_json::Value::String(value) => Ok(Some(value)),
            serde_json::Value::Null => Ok(None),
            value => Ok(Some(value.to_string())),
        }
    }

    async fn read_current_url(
        &self,
        frame_selector: Option<&str>,
    ) -> Result<Option<String>, BlobError> {
        self.inner.current_url_in_frame(frame_selector).await
    }

    async fn read_request_header(
        &self,
        request: &blob_core::BrowserFlowRequest,
        header_name: &str,
    ) -> Result<Option<String>, BlobError> {
        self.inner.read_request_header(request, header_name).await
    }

    async fn read_request_field(
        &self,
        request: &blob_core::BrowserFlowRequest,
        field_name: &str,
    ) -> Result<Option<String>, BlobError> {
        self.inner.read_request_field(request, field_name).await
    }
}

impl ProviderCredentialRecord {
    fn normalize(mut self) -> Self {
        self.token = normalize_secret_field(self.token);
        self.browser_id = normalize_secret_field(self.browser_id);
        self.cookie_header = normalize_secret_field(self.cookie_header);
        self.family_id = normalize_secret_field(self.family_id);
        self.root_folder_id = normalize_secret_field(self.root_folder_id);
        self.user_domain_id = normalize_secret_field(self.user_domain_id);
        self.client_id = normalize_secret_field(self.client_id);
        self.tenant = normalize_secret_field(self.tenant);
        self.drive_id = normalize_secret_field(self.drive_id);
        self.redirect_url = normalize_secret_field(self.redirect_url);
        self.quota_min_free = normalize_secret_field(self.quota_min_free);
        self.quota_max_used = normalize_secret_field(self.quota_max_used);
        self.personal_quota_min_free = normalize_secret_field(self.personal_quota_min_free);
        self.personal_quota_max_used = normalize_secret_field(self.personal_quota_max_used);
        self.family_quota_min_free = normalize_secret_field(self.family_quota_min_free);
        self.family_quota_max_used = normalize_secret_field(self.family_quota_max_used);
        self.browser_profile = self
            .browser_profile
            .map(BrowserRequestProfile::normalize)
            .filter(|profile| !profile.is_empty());
        self
    }

    fn is_empty(&self) -> bool {
        self.token.is_none()
            && self.browser_id.is_none()
            && self.cookie_header.is_none()
            && self.family_id.is_none()
            && self.root_folder_id.is_none()
            && self.user_domain_id.is_none()
            && self.client_id.is_none()
            && self.tenant.is_none()
            && self.drive_id.is_none()
            && self.redirect_url.is_none()
            && self.quota_min_free.is_none()
            && self.quota_max_used.is_none()
            && self.personal_quota_min_free.is_none()
            && self.personal_quota_max_used.is_none()
            && self.family_quota_min_free.is_none()
            && self.family_quota_max_used.is_none()
            && self.browser_profile.is_none()
    }
}

impl From<ProviderCredentialInput> for ProviderCredentialRecord {
    fn from(value: ProviderCredentialInput) -> Self {
        Self {
            token: value.token,
            browser_id: value.browser_id,
            cookie_header: value.cookie_header,
            family_id: value.family_id,
            root_folder_id: value.root_folder_id,
            user_domain_id: value.user_domain_id,
            client_id: value.client_id,
            tenant: value.tenant,
            drive_id: value.drive_id,
            redirect_url: value.redirect_url,
            quota_min_free: value.quota_min_free,
            quota_max_used: value.quota_max_used,
            personal_quota_min_free: value.personal_quota_min_free,
            personal_quota_max_used: value.personal_quota_max_used,
            family_quota_min_free: value.family_quota_min_free,
            family_quota_max_used: value.family_quota_max_used,
            browser_profile: value.browser_profile,
        }
        .normalize()
    }
}

impl AppConfig {
    fn from_env() -> Result<Self> {
        let bind_addr: SocketAddr = env::var("CCBG_BIND_ADDR")
            .unwrap_or_else(|_| "127.0.0.1:61080".to_string())
            .parse()
            .context("invalid CCBG_BIND_ADDR")?;
        validate_port_range(bind_addr.port())?;
        let admin_bind_addr: SocketAddr = env::var("CCBG_ADMIN_BIND_ADDR")
            .unwrap_or_else(|_| "127.0.0.1:61081".to_string())
            .parse()
            .context("invalid CCBG_ADMIN_BIND_ADDR")?;
        validate_port_range(admin_bind_addr.port())?;
        let auth_callback_bind_addr: SocketAddr = env::var("CCBG_AUTH_CALLBACK_BIND_ADDR")
            .unwrap_or_else(|_| "127.0.0.1:61082".to_string())
            .parse()
            .context("invalid CCBG_AUTH_CALLBACK_BIND_ADDR")?;
        validate_port_range(auth_callback_bind_addr.port())?;
        let metrics_bind_addr: SocketAddr = env::var("CCBG_METRICS_BIND_ADDR")
            .unwrap_or_else(|_| "127.0.0.1:61083".to_string())
            .parse()
            .context("invalid CCBG_METRICS_BIND_ADDR")?;
        validate_port_range(metrics_bind_addr.port())?;
        let admin_mode = AdminMode::parse(&env_or("CCBG_ADMIN_MODE", "web"))?;

        let onedrive_enabled = env_bool("CCBG_ONEDRIVE_ENABLED", false);
        let primary_provider = ProviderId::parse(
            &env::var("CCBG_PRIMARY_PROVIDER")
                .or_else(|_| env::var("CCBG_PROVIDER"))
                .unwrap_or_else(|_| "unicom".to_string()),
        )?;
        let sync_targets = parse_provider_list(&env::var("CCBG_SYNC_TARGETS").unwrap_or_default())?;
        let fallback_read_order =
            parse_provider_list(&env::var("CCBG_FALLBACK_READ_ORDER").unwrap_or_default())?;
        let replication_mode =
            ReplicationMode::parse(&env_or("CCBG_REPLICATION_MODE", "async_backup"))?;
        let topology = TopologyPolicy::from_input(TopologyInput {
            primary_provider,
            sync_targets,
            fallback_read_order,
            onedrive_enabled,
            replication_mode,
        })?;
        let control_plane_file = env_or("CCBG_CONTROL_PLANE_FILE", "./data/control-plane.json");
        let credentials_dir = env_or("CCBG_CREDENTIALS_DIR", "./data/provider-credentials");
        let instance_id_file = env_or("CCBG_INSTANCE_ID_FILE", "./data/instance-id");
        let instance_id = resolve_gateway_instance_id(&instance_id_file, &control_plane_file)?;
        let managed_root_base =
            normalize_managed_root_base(&env_or("CCBG_MANAGED_ROOT_BASE", "ccbg-managed"))
                .unwrap_or_else(|| "ccbg-managed".to_string());
        let managed_root_suffix = managed_root_suffix_from_instance_id(&instance_id);
        let onedrive_root_prefix = Some(effective_managed_root_prefix_from_parts(
            env_opt("CCBG_ONEDRIVE_ROOT_PREFIX").as_deref(),
            managed_root_base.as_str(),
            managed_root_suffix.as_str(),
        ));

        Ok(Self {
            bind_addr,
            admin_mode,
            admin_bind_addr,
            auth_callback_bind_addr,
            metrics_bind_addr,
            notify_webhook_url: env_opt("CCBG_NOTIFY_WEBHOOK_URL"),
            notify_webhook_signing_secret: env_opt_or_file(
                "CCBG_NOTIFY_WEBHOOK_SIGNING_SECRET",
                "CCBG_NOTIFY_WEBHOOK_SIGNING_SECRET_FILE",
            ),
            notify_poll_interval_seconds: env_u64("CCBG_NOTIFY_POLL_INTERVAL_SECONDS", 15).max(5),
            replication_failed_alert_threshold: env_usize(
                "CCBG_REPLICATION_FAILED_ALERT_THRESHOLD",
                1,
            )
            .max(1),
            replication_failed_alert_min_age_ms: env_u64(
                "CCBG_REPLICATION_FAILED_ALERT_MIN_AGE_MS",
                0,
            ),
            control_plane_file,
            credentials_dir,
            instance_id_file,
            managed_root_base,
            managed_root_suffix,
            browser_flow_catalog_dir: env_or(
                "CCBG_BROWSER_FLOW_CATALOG_DIR",
                "./config/browser-flows",
            ),
            provider_bridge_catalog_dir: env_or(
                "CCBG_PROVIDER_BRIDGE_CATALOG_DIR",
                "./config/provider-bridges",
            ),
            provider_capability_catalog_dir: env_or(
                "CCBG_PROVIDER_CAPABILITY_CATALOG_DIR",
                "./config/provider-capabilities",
            ),
            admin_username: env_opt_or_file("CCBG_ADMIN_USERNAME", "CCBG_ADMIN_USERNAME_FILE"),
            admin_password_hash: env_opt_or_file(
                "CCBG_ADMIN_PASSWORD_HASH",
                "CCBG_ADMIN_PASSWORD_HASH_FILE",
            ),
            admin_password_plain: env_opt_or_file(
                "CCBG_ADMIN_PASSWORD",
                "CCBG_ADMIN_PASSWORD_FILE",
            ),
            admin_session_ttl_seconds: env_u64(
                "CCBG_ADMIN_SESSION_TTL_SECONDS",
                DEFAULT_ADMIN_SESSION_TTL_SECONDS,
            )
            .max(300),
            control_api_key: env_opt_or_file("CCBG_CONTROL_API_KEY", "CCBG_CONTROL_API_KEY_FILE"),
            topology,
            s3_access_key_id: env_or("CCBG_S3_ACCESS_KEY_ID", "ccbg"),
            s3_secret_access_key: env_or("CCBG_S3_SECRET_ACCESS_KEY", "change-me"),
            s3_region: env_or("CCBG_S3_REGION", "us-east-1"),
            metadata_db_path: env_or("CCBG_METADATA_DB_PATH", "./data/ccbg.db"),
            metadata_snapshot_recent_limit: env_usize("CCBG_METADATA_SNAPSHOT_RECENT_LIMIT", 32),
            metadata_retention: MetadataRetentionPolicy {
                completed_history_limit: env_usize("CCBG_METADATA_COMPLETED_HISTORY_LIMIT", 512),
                failed_history_limit: env_usize("CCBG_METADATA_FAILED_HISTORY_LIMIT", 256),
            },
            replication_workers: env_usize("CCBG_REPLICATION_WORKERS", 2),
            data_plane_max_in_flight: env_usize("CCBG_DATA_PLANE_MAX_IN_FLIGHT", 8).max(1),
            data_plane_max_requests_per_second: env_usize(
                "CCBG_DATA_PLANE_MAX_REQUESTS_PER_SECOND",
                0,
            ),
            replication_recent_limit: env_usize("CCBG_REPLICATION_RECENT_LIMIT", 64),
            replication_max_attempts: env_u64("CCBG_REPLICATION_MAX_ATTEMPTS", 3) as u32,
            replication_base_retry_delay_ms: env_u64("CCBG_REPLICATION_BASE_RETRY_DELAY_MS", 1_000),
            replication_max_retry_delay_ms: env_u64("CCBG_REPLICATION_MAX_RETRY_DELAY_MS", 30_000),
            object_action_history_limit: env_usize(
                "CCBG_OBJECT_ACTION_HISTORY_LIMIT",
                DEFAULT_OBJECT_ACTION_HISTORY_LIMIT,
            ),
            max_in_memory_object_bytes: env_usize(
                "CCBG_MAX_IN_MEMORY_OBJECT_BYTES",
                8 * 1024 * 1024,
            ),
            max_spooled_object_bytes: env_u64("CCBG_MAX_SPOOLED_OBJECT_BYTES", 0),
            spooled_body_chunk_bytes: env_usize("CCBG_SPOOLED_BODY_CHUNK_BYTES", 1024 * 1024)
                .max(1),
            body_spool_dir: env_opt("CCBG_BODY_SPOOL_DIR"),
            onedrive: OneDriveConfig {
                enabled: onedrive_enabled,
                tenant: env_or("CCBG_ONEDRIVE_TENANT", "common"),
                client_id: env_opt("CCBG_ONEDRIVE_CLIENT_ID"),
                use_device_code: env_bool("CCBG_ONEDRIVE_USE_DEVICE_CODE", false),
                redirect_url: env_opt("CCBG_ONEDRIVE_REDIRECT_URL"),
                drive_id: env_opt("CCBG_ONEDRIVE_DRIVE_ID"),
                graph_base_url: env_or(
                    "CCBG_ONEDRIVE_GRAPH_BASE_URL",
                    "https://graph.microsoft.com/v1.0",
                ),
                auth_base_url: env_or(
                    "CCBG_ONEDRIVE_AUTH_BASE_URL",
                    DEFAULT_ONEDRIVE_AUTH_BASE_URL,
                ),
                scopes: env_or("CCBG_ONEDRIVE_SCOPES", DEFAULT_ONEDRIVE_SCOPES),
                session_file: Some(
                    env_opt("CCBG_ONEDRIVE_SESSION_FILE")
                        .unwrap_or_else(|| "./data/onedrive-session.json".to_string()),
                ),
                token_source: resolve_token_source("CCBG_ONEDRIVE"),
                root_prefix: onedrive_root_prefix,
                user_agent: env_or("CCBG_ONEDRIVE_USER_AGENT", "carrier-cloud-blob-gateway/0.1"),
                request_timeout_secs: env_u64("CCBG_ONEDRIVE_TIMEOUT_SECS", 30),
                max_single_upload_bytes: env_byte_size_limit(
                    "CCBG_ONEDRIVE_MAX_SINGLE_UPLOAD_BYTES",
                )?,
                max_single_download_bytes: env_byte_size_limit(
                    "CCBG_ONEDRIVE_MAX_SINGLE_DOWNLOAD_BYTES",
                )?,
            },
        })
    }
}

fn validate_port_range(port: u16) -> Result<()> {
    if (60000..=65534).contains(&port) {
        Ok(())
    } else {
        anyhow::bail!("CCBG_BIND_ADDR port must be between 60000 and 65534, got {port}")
    }
}

