async fn update_smb_sidecar_config(
    State(state): State<AppState>,
    Json(input): Json<SmbSidecarUpdateInput>,
) -> Result<Json<SmbSidecarSummaryPayload>, ApiError> {
    let applications = current_data_plane_applications(&state);
    let next = {
        let control_plane = state
            .control_plane
            .lock()
            .expect("control plane state poisoned");
        normalize_smb_sidecar_with_existing(input.smb, &control_plane.smb_sidecar, &applications)?
    };
    {
        let mut control_plane = state
            .control_plane
            .lock()
            .expect("control plane state poisoned");
        control_plane.smb_sidecar = next;
        persist_control_plane_state(&state.config.control_plane_file, &control_plane)
            .map_err(|error| BlobError::Configuration(error.to_string()))?;
    }
    Ok(Json(current_smb_sidecar_payload(&state)))
}

async fn export_smb_sidecar_bundle(State(state): State<AppState>) -> Result<Response, ApiError> {
    let config = current_smb_sidecar_config(&state);
    let bundle = build_smb_export_bundle(&state, &config)?;
    let body = build_smb_export_bundle_tar(&bundle)?;
    let filename = format!("{}.tar", bundle.bundle_name);
    let mut response = Response::new(Body::from(body));
    response
        .headers_mut()
        .insert(CONTENT_TYPE, HeaderValue::from_static("application/x-tar"));
    response.headers_mut().insert(
        CONTENT_DISPOSITION,
        HeaderValue::from_str(&format!("attachment; filename=\"{filename}\""))
            .map_err(|error| BlobError::Configuration(error.to_string()))?,
    );
    Ok(response)
}

