async fn generate_managed_encryption_key(
    State(state): State<AppState>,
    Json(input): Json<ManagedEncryptionKeyGenerateInput>,
) -> Result<Json<ManagedEncryptionKeyPayload>, ApiError> {
    let id = normalize_managed_encryption_key_id(&input.id)?;
    match load_managed_encryption_key_record(&state.config, &id) {
        Ok(_) => {
            return Err(ApiError(BlobError::Configuration(format!(
                "managed encryption key already exists: {id}"
            ))));
        }
        Err(BlobError::NotFound(_)) => {}
        Err(error) => return Err(ApiError(error)),
    }

    let mut bytes = vec![0u8; ManagedEncryptionKeyKind::Raw256Bit.key_material_len()];
    OsRng.fill_bytes(&mut bytes);
    let now = current_unix_ms();
    let record = ManagedEncryptionKeyRecord {
        schema_version: MANAGED_ENCRYPTION_KEY_RECORD_SCHEMA_VERSION,
        id,
        label: normalize_secret_field(input.label),
        kind: ManagedEncryptionKeyKind::Raw256Bit,
        key_material_base64: BASE64_STANDARD.encode(bytes),
        created_at_unix_ms: now,
        updated_at_unix_ms: now,
        notes: normalize_secret_field(input.notes),
    };
    persist_managed_encryption_key_record(&state.config, &record)?;
    Ok(Json(managed_encryption_key_payload(
        &record,
        &current_encryption_profiles(&state),
    )?))
}

async fn export_managed_encryption_key(
    State(state): State<AppState>,
    Path(key_id): Path<String>,
) -> Result<Json<ManagedEncryptionKeyBackupPayload>, ApiError> {
    let record = load_managed_encryption_key_record(&state.config, &key_id)?;
    Ok(Json(ManagedEncryptionKeyBackupPayload {
        backup_format_version: MANAGED_ENCRYPTION_KEY_BACKUP_FORMAT_VERSION,
        exported_at_unix_ms: current_unix_ms(),
        gateway_version: env!("CARGO_PKG_VERSION").to_string(),
        key: record,
    }))
}

async fn import_managed_encryption_key_backup(
    State(state): State<AppState>,
    Json(input): Json<ManagedEncryptionKeyBackupPayload>,
) -> Result<Json<ManagedEncryptionKeyPayload>, ApiError> {
    if input.backup_format_version != MANAGED_ENCRYPTION_KEY_BACKUP_FORMAT_VERSION {
        return Err(ApiError(BlobError::Configuration(format!(
            "unsupported managed encryption key backup format version {}",
            input.backup_format_version
        ))));
    }
    let mut record = normalize_managed_encryption_key_record(input.key)?;
    match load_managed_encryption_key_record(&state.config, &record.id) {
        Ok(existing) => {
            if existing.key_material_base64 != record.key_material_base64 {
                return Err(ApiError(BlobError::Configuration(format!(
                    "managed encryption key {} already exists with different key material",
                    record.id
                ))));
            }
            record.created_at_unix_ms = existing.created_at_unix_ms.max(record.created_at_unix_ms);
        }
        Err(BlobError::NotFound(_)) => {}
        Err(error) => return Err(ApiError(error)),
    }
    let now = current_unix_ms();
    if record.created_at_unix_ms == 0 {
        record.created_at_unix_ms = now;
    }
    record.updated_at_unix_ms = now;
    persist_managed_encryption_key_record(&state.config, &record)?;
    Ok(Json(managed_encryption_key_payload(
        &record,
        &current_encryption_profiles(&state),
    )?))
}

async fn delete_managed_encryption_key(
    State(state): State<AppState>,
    Path(key_id): Path<String>,
) -> Result<StatusCode, ApiError> {
    let key_id = normalize_managed_encryption_key_id(&key_id)?;
    let profiles = current_encryption_profiles(&state);
    let references = encryption_profile_referencing_managed_key(&profiles, &key_id);
    if !references.is_empty() {
        return Err(ApiError(BlobError::Configuration(format!(
            "managed encryption key {} is still referenced by encryption profile(s): {}",
            key_id,
            references.join(", ")
        ))));
    }
    remove_managed_encryption_key_record(&state.config, &key_id)?;
    Ok(StatusCode::NO_CONTENT)
}

