fn content_type_matches(patterns: &[String], content_type: Option<&str>) -> bool {
    if patterns.is_empty() {
        return true;
    }
    let Some(content_type) = content_type else {
        return false;
    };
    let content_type = content_type.trim().to_ascii_lowercase();
    patterns.iter().any(|pattern| {
        if let Some(prefix) = pattern.strip_suffix("/*") {
            content_type.starts_with(&format!("{prefix}/"))
        } else {
            pattern == &content_type
        }
    })
}

fn content_policy_matches(
    policy: &ContentPolicyRule,
    application_id: Option<&str>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> bool {
    if !policy.enabled {
        return false;
    }
    if !policy.application_ids.is_empty() {
        let Some(application_id) = application_id else {
            return false;
        };
        if !policy.application_ids.iter().any(|id| id == application_id) {
            return false;
        }
    }
    if !policy.buckets.is_empty() && !policy.buckets.iter().any(|value| value == bucket) {
        return false;
    }
    if !policy.prefixes.is_empty() && !policy.prefixes.iter().any(|prefix| key.starts_with(prefix))
    {
        return false;
    }
    content_type_matches(&policy.content_types, content_type)
}

fn matching_content_policy(
    state: &AppState,
    application_id: Option<&str>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> Option<ContentPolicyRule> {
    current_content_policies(state)
        .into_iter()
        .find(|policy| content_policy_matches(policy, application_id, bucket, key, content_type))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct S3ApplicationIdentity {
    application_id: String,
    access_key_id: String,
    permissions: DataPlaneApplicationPermissions,
}

fn resolve_s3_application(
    state: &AppState,
    access_key_id: &str,
) -> Option<(S3ApplicationIdentity, String)> {
    current_data_plane_applications(state)
        .into_iter()
        .find(|application| application.enabled && application.access_key_id == access_key_id)
        .map(|application| {
            (
                S3ApplicationIdentity {
                    application_id: application.id,
                    access_key_id: application.access_key_id,
                    permissions: application.permissions,
                },
                application.secret_access_key,
            )
        })
}

fn normalize_probe_key_prefix(value: Option<&str>) -> String {
    let normalized = value
        .unwrap_or("ccbg-limit-probes")
        .trim()
        .trim_matches('/')
        .to_string();
    if normalized.is_empty() {
        "ccbg-limit-probes".to_string()
    } else {
        normalized
    }
}

#[derive(Debug, Clone, Copy)]
enum S3ActionKind {
    ListBuckets,
    ListObjects,
    ReadObject,
    WriteObject,
    DeleteObject,
}

impl S3ActionKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::ListBuckets => "list_buckets",
            Self::ListObjects => "list_objects",
            Self::ReadObject => "read_object",
            Self::WriteObject => "write_object",
            Self::DeleteObject => "delete_object",
        }
    }
}

fn data_plane_permission_allowed(
    permissions: &DataPlaneApplicationPermissions,
    action: S3ActionKind,
    bucket: Option<&str>,
    key: Option<&str>,
) -> bool {
    let action_allowed = match action {
        S3ActionKind::ListBuckets => permissions.list_buckets,
        S3ActionKind::ListObjects => permissions.list_objects,
        S3ActionKind::ReadObject => permissions.read_object,
        S3ActionKind::WriteObject => permissions.write_object,
        S3ActionKind::DeleteObject => permissions.delete_object,
    };
    if !action_allowed {
        return false;
    }
    if matches!(action, S3ActionKind::ListBuckets) {
        return true;
    }
    if !permissions.allowed_buckets.is_empty() {
        let Some(bucket) = bucket else {
            return false;
        };
        if !permissions
            .allowed_buckets
            .iter()
            .any(|value| value == bucket)
        {
            return false;
        }
    }
    if matches!(action, S3ActionKind::ListObjects) && key.is_none() {
        return true;
    }
    if !permissions.allowed_prefixes.is_empty() {
        let Some(key) = key else {
            return false;
        };
        let prefix_allowed = match action {
            S3ActionKind::ListObjects => permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| list_prefix_overlaps_allowed_prefix(key, prefix)),
            _ => permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| object_key_matches_allowed_prefix(key, prefix)),
        };
        if !prefix_allowed {
            return false;
        }
    }
    true
}

fn object_key_matches_allowed_prefix(key: &str, allowed_prefix: &str) -> bool {
    if allowed_prefix.is_empty() {
        return true;
    }
    key == allowed_prefix
        || key
            .strip_prefix(allowed_prefix)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn list_prefix_overlaps_allowed_prefix(request_prefix: &str, allowed_prefix: &str) -> bool {
    request_prefix.is_empty()
        || object_key_matches_allowed_prefix(request_prefix, allowed_prefix)
        || allowed_prefix.starts_with(request_prefix)
}

fn ensure_s3_application_permission(
    application: &S3ApplicationIdentity,
    action: S3ActionKind,
    bucket: Option<&str>,
    key: Option<&str>,
) -> Result<(), S3Error> {
    if data_plane_permission_allowed(&application.permissions, action, bucket, key) {
        return Ok(());
    }
    let scope = match (bucket, key) {
        (Some(bucket), Some(key)) => format!("{bucket}/{key}"),
        (Some(bucket), None) => bucket.to_string(),
        (None, _) => "gateway".to_string(),
    };
    Err(S3Error::access_denied(format!(
        "Application {} is not allowed to perform {} on {}.",
        application.application_id,
        action.as_str(),
        scope
    )))
}

fn filter_containers_for_application(
    containers: Vec<blob_core::ContainerInfo>,
    application: &S3ApplicationIdentity,
) -> Vec<blob_core::ContainerInfo> {
    if application.permissions.allowed_buckets.is_empty() {
        return containers;
    }
    containers
        .into_iter()
        .filter(|container| {
            application
                .permissions
                .allowed_buckets
                .iter()
                .any(|bucket| bucket == &container.name)
        })
        .collect()
}

fn filter_objects_for_application(
    objects: Vec<blob_core::ObjectInfo>,
    application: &S3ApplicationIdentity,
) -> Vec<blob_core::ObjectInfo> {
    if application.permissions.allowed_prefixes.is_empty() {
        return objects;
    }
    objects
        .into_iter()
        .filter(|object| {
            application
                .permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| object_key_matches_allowed_prefix(&object.key, prefix))
        })
        .collect()
}

fn provider_limit_probe_sizes(input: &ProviderLimitProbeInput) -> Result<Vec<u64>, BlobError> {
    let mut sizes = Vec::new();
    for raw in &input.sizes {
        sizes.push(parse_byte_size_limit(raw).map_err(|error| {
            BlobError::Configuration(format!("invalid limit probe size '{raw}': {error}"))
        })?);
    }
    sizes.extend(input.sizes_bytes.iter().copied());
    sizes.sort_unstable();
    sizes.dedup();
    sizes.retain(|size| *size > 0);
    if sizes.is_empty() {
        return Err(BlobError::Configuration(
            "limit probe requires at least one positive size in sizes or sizes_bytes".to_string(),
        ));
    }
    sizes.sort_unstable_by(|left, right| right.cmp(left));
    Ok(sizes)
}

fn provider_limit_probe_chunk_sizes(
    input: &ProviderLimitProbeInput,
    capabilities: &blob_core::BackendCapabilities,
) -> Result<Vec<u64>, BlobError> {
    let requested_chunk = match (input.chunk_size.as_deref(), input.chunk_size_bytes) {
        (Some(raw), _) if !raw.trim().is_empty() => {
            Some(parse_byte_size_limit(raw).map_err(|error| {
                BlobError::Configuration(format!("invalid limit probe chunk_size '{raw}': {error}"))
            })?)
        }
        (_, Some(value)) if value > 0 => Some(value),
        _ => None,
    };
    let capability_chunk = capabilities
        .upload_part_size_bytes
        .filter(|value| *value > 0);
    let max_chunk = PROVIDER_LIMIT_PROBE_MAX_STREAM_CHUNK_BYTES.max(1);
    let mut current = requested_chunk
        .into_iter()
        .chain(capability_chunk)
        .max()
        .unwrap_or(PROVIDER_LIMIT_PROBE_DEFAULT_CHUNK_SIZE_BYTES)
        .clamp(1, max_chunk);
    let min_chunk = current
        .min(PROVIDER_LIMIT_PROBE_MIN_CHUNK_SIZE_BYTES)
        .max(1);
    let mut sizes = Vec::new();
    loop {
        sizes.push(current);
        if current <= min_chunk {
            break;
        }
        let next = (current / 2).max(min_chunk);
        if next == current {
            break;
        }
        current = next;
    }
    for extra in [requested_chunk, capability_chunk] {
        if let Some(extra) = extra {
            sizes.push(extra.clamp(1, max_chunk));
        }
    }
    sizes.sort_unstable_by(|left, right| right.cmp(left));
    sizes.dedup();
    Ok(sizes)
}

fn zero_probe_body(size: u64, chunk_size: u64) -> ObjectBody {
    let chunk_size = chunk_size.max(1).min(usize::MAX as u64) as usize;
    let template = Bytes::from(vec![0u8; chunk_size]);
    ObjectBody::from_stream(stream::try_unfold(size, move |remaining| {
        let template = template.clone();
        async move {
            if remaining == 0 {
                return Ok(None);
            }
            let next_len = remaining.min(chunk_size as u64) as usize;
            Ok(Some((
                template.slice(0..next_len),
                remaining.saturating_sub(next_len as u64),
            )))
        }
    }))
}

fn provider_limit_probe_read_progress_interval(input: &ProviderLimitProbeInput) -> Duration {
    Duration::from_millis(
        input
            .read_progress_interval_ms
            .unwrap_or(PROVIDER_LIMIT_PROBE_DEFAULT_READ_PROGRESS_INTERVAL_MS)
            .clamp(250, 60_000),
    )
}

fn provider_limit_probe_read_total_timeout(size: u64, input: &ProviderLimitProbeInput) -> Duration {
    let timeout_ms = if let Some(timeout_ms) = input.read_total_timeout_ms {
        timeout_ms.clamp(
            1_000,
            PROVIDER_LIMIT_PROBE_MAX_READ_TOTAL_TIMEOUT_SECS * 1_000,
        )
    } else {
        let size_floor_secs = (size
            .saturating_add(PROVIDER_LIMIT_PROBE_MIN_ASSUMED_READ_BYTES_PER_SEC - 1)
            / PROVIDER_LIMIT_PROBE_MIN_ASSUMED_READ_BYTES_PER_SEC)
            .saturating_add(PROVIDER_LIMIT_PROBE_READ_TIMEOUT_OVERHEAD_SECS);
        PROVIDER_LIMIT_PROBE_DEFAULT_READ_TOTAL_TIMEOUT_SECS
            .max(size_floor_secs)
            .min(PROVIDER_LIMIT_PROBE_MAX_READ_TOTAL_TIMEOUT_SECS)
            .saturating_mul(1_000)
    };
    Duration::from_millis(timeout_ms)
}

fn provider_limit_probe_read_progress_snapshot(
    read_bytes: u64,
    started_at_unix_ms: u64,
    first_progress_latency_ms: &AtomicU64,
) -> ProviderLimitProbeReadProgress {
    let elapsed_ms = current_unix_ms().saturating_sub(started_at_unix_ms).max(1);
    let first_response_latency_ms = match first_progress_latency_ms.load(Ordering::SeqCst) {
        0 => None,
        value => Some(value),
    };
    ProviderLimitProbeReadProgress {
        read_bytes,
        elapsed_ms,
        first_response_latency_ms,
        bytes_per_sec: provider_io_throughput_bytes_per_sec(read_bytes, elapsed_ms),
    }
}

async fn drain_probe_body_with_first_progress<F>(
    body: ObjectBody,
    started_at_unix_ms: u64,
    total_timeout: Duration,
    progress_interval: Duration,
    mut on_progress: F,
) -> Result<(u64, Option<u64>), ProviderLimitProbeReadDrainError>
where
    F: FnMut(ProviderLimitProbeReadProgress),
{
    let first_progress_latency_ms = Arc::new(AtomicU64::new(0));
    let observer = StreamFirstProgressObserver::new({
        let first_progress_latency_ms = Arc::clone(&first_progress_latency_ms);
        move || {
            first_progress_latency_ms.store(
                current_unix_ms().saturating_sub(started_at_unix_ms).max(1),
                Ordering::SeqCst,
            );
        }
    });
    let mut stream = body.observe_first_progress(observer).into_stream();
    let deadline = Instant::now() + total_timeout;
    let mut read_bytes = 0u64;
    let mut last_progress_elapsed_ms = 0u64;
    while let Some(chunk) = timeout_at(deadline, stream.next()).await.map_err(|_| {
        let progress = provider_limit_probe_read_progress_snapshot(
            read_bytes,
            started_at_unix_ms,
            &first_progress_latency_ms,
        );
        ProviderLimitProbeReadDrainError {
            error: BlobError::Upstream(format!(
                "read-back exceeded total timeout of {}s after reading {} bytes",
                total_timeout.as_secs(),
                progress.read_bytes
            )),
            read_bytes: progress.read_bytes,
            elapsed_ms: progress.elapsed_ms,
            first_response_latency_ms: progress.first_response_latency_ms,
            bytes_per_sec: progress.bytes_per_sec,
        }
    })? {
        let chunk = chunk.map_err(|error| {
            let progress = provider_limit_probe_read_progress_snapshot(
                read_bytes,
                started_at_unix_ms,
                &first_progress_latency_ms,
            );
            ProviderLimitProbeReadDrainError {
                error,
                read_bytes: progress.read_bytes,
                elapsed_ms: progress.elapsed_ms,
                first_response_latency_ms: progress.first_response_latency_ms,
                bytes_per_sec: progress.bytes_per_sec,
            }
        })?;
        read_bytes = read_bytes.saturating_add(chunk.len() as u64);
        let progress = provider_limit_probe_read_progress_snapshot(
            read_bytes,
            started_at_unix_ms,
            &first_progress_latency_ms,
        );
        if progress.elapsed_ms.saturating_sub(last_progress_elapsed_ms)
            >= progress_interval.as_millis() as u64
        {
            on_progress(progress);
            last_progress_elapsed_ms = progress.elapsed_ms;
        }
    }
    let first_progress_latency_ms = match first_progress_latency_ms.load(Ordering::SeqCst) {
        0 => None,
        value => Some(value),
    };
    Ok((read_bytes, first_progress_latency_ms))
}

fn env_u64(key: &str, default: u64) -> u64 {
    env::var(key)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(default)
}

fn env_byte_size_limit(key: &str) -> Result<Option<u64>, BlobError> {
    env_opt(key)
        .map(|value| {
            parse_byte_size_limit(&value)
                .map_err(|error| BlobError::Configuration(format!("invalid {key}: {error}")))
        })
        .transpose()
}

fn env_usize(key: &str, default: usize) -> usize {
    env::var(key)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(default)
}

async fn index(State(state): State<AppState>) -> Json<IndexPayload> {
    let snapshot = state.replication.snapshot();
    let topology = runtime_topology(&state);
    let backend_name = backend_for_provider(&state, topology.primary_provider)
        .map(|backend| backend.name())
        .unwrap_or("unknown");

    Json(IndexPayload {
        service: "carrier-cloud-blob-gateway",
        backend: backend_name,
        primary_provider: topology.primary_provider_name(),
        sync_targets: topology.sync_target_names(),
        fallback_read_order: topology.fallback_read_order_names(),
        replication: ReplicationQueueSummary {
            pending_jobs: snapshot.pending_count,
            recent_jobs: snapshot.recent_count,
        },
        endpoints: vec![
            "/",
            "/{bucket}",
            "/{bucket}/{key}",
            "/healthz",
            "/__ccbg",
            "/__ccbg/providers",
            "/__ccbg/replication",
            "/v1/containers",
            "/v1/objects",
        ],
    })
}

async fn list_provider_health(
    State(state): State<AppState>,
) -> Result<Json<Vec<BackendPayload>>, ApiError> {
    Ok(Json(provider_health_payloads(&state).await?))
}

async fn replication_snapshot(
    State(state): State<AppState>,
) -> Result<Json<ReplicationStatePayload>, ApiError> {
    Ok(Json(replication_state_payload(&state)?))
}

async fn healthz(
    State(state): State<AppState>,
) -> Result<Json<blob_core::ServiceHealth>, ApiError> {
    let (_, backend) = current_primary_backend(&state)?;
    Ok(Json(backend.health().await?))
}

#[derive(Debug, Serialize)]
struct ExtendedHealthPayload {
    status: &'static str,
    ready: bool,
    checked_at_unix_ms: u64,
    runtime: RuntimeStatusPayload,
    monitoring: MonitoringSummaryPayload,
    alerts: Vec<AdminAlertPayload>,
}

async fn metrics_healthz(
    State(state): State<AppState>,
) -> Result<Json<ExtendedHealthPayload>, ApiError> {
    let replication_state = replication_state_payload(&state)?;
    let provider_health = provider_health_payloads(&state).await?;
    let onedrive_auth = read_onedrive_auth_status(&state);
    let alerts = build_admin_alerts(&state, &provider_health, &replication_state, &onedrive_auth);
    let object_action_history = control_plane_snapshot(&state).object_action_history;
    let monitoring = monitoring_summary_payload(
        &provider_health,
        &replication_state,
        &object_action_history,
        &alerts,
    );
    let ready = provider_health.iter().all(|provider| {
        provider.role != "primary"
            || !matches!(provider.health.status, blob_core::HealthStatus::Unavailable)
    });

    Ok(Json(ExtendedHealthPayload {
        status: if ready { "ok" } else { "degraded" },
        ready,
        checked_at_unix_ms: current_unix_ms(),
        runtime: runtime_status_payload(&state),
        monitoring,
        alerts,
    }))
}

async fn metrics_readyz(State(state): State<AppState>) -> Result<StatusCode, ApiError> {
    let provider_health = provider_health_payloads(&state).await?;
    let primary_ready = provider_health.iter().all(|provider| {
        provider.role != "primary"
            || !matches!(provider.health.status, blob_core::HealthStatus::Unavailable)
    });

    Ok(if primary_ready {
        StatusCode::OK
    } else {
        StatusCode::SERVICE_UNAVAILABLE
    })
}

async fn metrics_prometheus(State(state): State<AppState>) -> Result<Response, ApiError> {
    let runtime = runtime_status_payload(&state);
    let replication_state = replication_state_payload(&state)?;
    let provider_health = provider_health_payloads(&state).await?;
    let onedrive_auth = read_onedrive_auth_status(&state);
    let alerts = build_admin_alerts(&state, &provider_health, &replication_state, &onedrive_auth);
    let object_action_history = control_plane_snapshot(&state).object_action_history;
    let monitoring = monitoring_summary_payload(
        &provider_health,
        &replication_state,
        &object_action_history,
        &alerts,
    );
    let data_plane_transfer = snapshot_data_plane_transfer(&state);

    let mut lines = Vec::new();
    lines.push("# HELP ccbg_up Carrier Cloud Blob Gateway process health indicator.".to_string());
    lines.push("# TYPE ccbg_up gauge".to_string());
    lines.push("ccbg_up 1".to_string());
    lines.push("# HELP ccbg_uptime_ms Gateway uptime in milliseconds.".to_string());
    lines.push("# TYPE ccbg_uptime_ms gauge".to_string());
    lines.push(format!("ccbg_uptime_ms {}", runtime.uptime_ms));
    lines.push(
        "# HELP ccbg_process_memory_bytes Gateway process memory usage in bytes.".to_string(),
    );
    lines.push("# TYPE ccbg_process_memory_bytes gauge".to_string());
    if let Some(value) = runtime.process_memory.rss_bytes {
        lines.push(format!(
            "ccbg_process_memory_bytes{{kind=\"rss\"}} {}",
            value
        ));
    }
    if let Some(value) = runtime.process_memory.virtual_bytes {
        lines.push(format!(
            "ccbg_process_memory_bytes{{kind=\"virtual\"}} {}",
            value
        ));
    }
    lines.push("# HELP ccbg_admin_alerts_open Current open alert count.".to_string());
    lines.push("# TYPE ccbg_admin_alerts_open gauge".to_string());
    lines.push(format!(
        "ccbg_admin_alerts_open {}",
        monitoring.open_alert_count
    ));
    lines.push(
        "# HELP ccbg_data_plane_concurrency_configured Configured max in-flight data-plane requests."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_concurrency_configured gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_concurrency_configured {}",
        runtime.data_plane_max_in_flight
    ));
    lines.push(
        "# HELP ccbg_data_plane_concurrency_available Currently available data-plane permits."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_concurrency_available gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_concurrency_available {}",
        state.data_plane_concurrency.semaphore.available_permits()
    ));
    let rate_limiter = snapshot_data_plane_rate_limiter(&state, current_unix_ms());
    lines.push(
        "# HELP ccbg_data_plane_rate_limit_configured Configured max data-plane requests per second (0 means disabled)."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_rate_limit_configured gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_rate_limit_configured {}",
        runtime.data_plane_max_requests_per_second
    ));
    lines.push(
        "# HELP ccbg_data_plane_rate_limit_current_second Data-plane requests observed in the current one-second window."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_rate_limit_current_second gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_rate_limit_current_second {}",
        rate_limiter.requests_in_window
    ));
    lines.push(
        "# HELP ccbg_data_plane_requests_total Total data-plane requests observed by the gateway."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_requests_total counter".to_string());
    lines.push(format!(
        "ccbg_data_plane_requests_total {}",
        data_plane_transfer.requests_total
    ));
    lines.push(
        "# HELP ccbg_data_plane_bytes_total Total data-plane bytes transferred by direction."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_bytes_total counter".to_string());
    lines.push(format!(
        "ccbg_data_plane_bytes_total{{direction=\"in\"}} {}",
        data_plane_transfer.bytes_in_total
    ));
    lines.push(format!(
        "ccbg_data_plane_bytes_total{{direction=\"out\"}} {}",
        data_plane_transfer.bytes_out_total
    ));
    lines.push("# HELP ccbg_provider_health Provider health status by role and provider (healthy=2,degraded=1,unavailable=0).".to_string());
    lines.push("# TYPE ccbg_provider_health gauge".to_string());
    for provider in &provider_health {
        let value = match provider.health.status {
            blob_core::HealthStatus::Healthy => 2,
            blob_core::HealthStatus::Degraded => 1,
            blob_core::HealthStatus::Unavailable => 0,
        };
        lines.push(format!(
            "ccbg_provider_health{{provider=\"{}\",role=\"{}\"}} {}",
            provider.provider, provider.role, value
        ));
    }
    lines.push(
        "# HELP ccbg_provider_io_operations_total Provider I/O operation counters by provider, operation, and outcome."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_operations_total counter".to_string());
    lines.push(
        "# HELP ccbg_provider_io_latency_ms Provider I/O observed latency in milliseconds."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_latency_ms gauge".to_string());
    lines.push(
        "# HELP ccbg_provider_io_bytes_per_second Provider I/O observed bytes per second."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_bytes_per_second gauge".to_string());
    for provider in &provider_health {
        for (operation_name, operation) in
            [("read", &provider.io.read), ("write", &provider.io.write)]
        {
            lines.push(format!(
                "ccbg_provider_io_operations_total{{provider=\"{}\",operation=\"{}\",outcome=\"success\"}} {}",
                provider.provider, operation_name, operation.success_count
            ));
            lines.push(format!(
                "ccbg_provider_io_operations_total{{provider=\"{}\",operation=\"{}\",outcome=\"failure\"}} {}",
                provider.provider, operation_name, operation.failure_count
            ));
            if let Some(value) = operation.first_success_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"first_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.first_response_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"first_response\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_success_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"last_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_response_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"last_response\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_success_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"last_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.rolling_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"rolling\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_large_success_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"last_large\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
        }
    }
    lines.push("# HELP ccbg_replication_jobs Replication jobs by persisted status.".to_string());
    lines.push("# TYPE ccbg_replication_jobs gauge".to_string());
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"pending\"}} {}",
        monitoring.replication.pending_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"retry_scheduled\"}} {}",
        monitoring.replication.retry_scheduled_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"failed\"}} {}",
        monitoring.replication.failed_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"completed\"}} {}",
        monitoring.replication.completed_jobs
    ));
    lines.push("# HELP ccbg_object_action_entries Object action history counts.".to_string());
    lines.push("# TYPE ccbg_object_action_entries gauge".to_string());
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"total\"}} {}",
        monitoring.object_actions.total_entries
    ));
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"successful\"}} {}",
        monitoring.object_actions.successful_entries
    ));
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"failed\"}} {}",
        monitoring.object_actions.failed_entries
    ));
    lines.push(
        "# HELP ccbg_object_action_unique_operators Unique operators in retained action history."
            .to_string(),
    );
    lines.push("# TYPE ccbg_object_action_unique_operators gauge".to_string());
    lines.push(format!(
        "ccbg_object_action_unique_operators {}",
        monitoring.object_actions.unique_operators
    ));
    lines.push(
        "# HELP ccbg_replication_target_jobs Replication job counters per target.".to_string(),
    );
    lines.push("# TYPE ccbg_replication_target_jobs gauge".to_string());
    for target in &replication_state.target_statuses {
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"queued\"}} {}",
            target.provider, target.queued_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"pending\"}} {}",
            target.provider, target.pending_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"retry_scheduled\"}} {}",
            target.provider, target.retry_scheduled_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"completed\"}} {}",
            target.provider, target.completed_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"failed\"}} {}",
            target.provider, target.failed_count
        ));
    }

    Ok((
        [(CONTENT_TYPE, "text/plain; version=0.0.4; charset=utf-8")],
        lines.join("\n") + "\n",
    )
        .into_response())
}

async fn list_containers(
    State(state): State<AppState>,
) -> Result<Json<Vec<blob_core::ContainerInfo>>, DataPlaneApiError> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())
        .map_err(DataPlaneApiError::from_s3_error)?;
    let _permit =
        try_acquire_data_plane_permit(&state).map_err(DataPlaneApiError::from_s3_error)?;
    let payload = list_containers_with_fallback(&state).await?.value;
    record_serialized_json_bytes(&state, &payload);
    Ok(Json(payload))
}

async fn list_objects(
    State(state): State<AppState>,
    Query(query): Query<ObjectsQuery>,
) -> Result<Json<Vec<blob_core::ObjectInfo>>, DataPlaneApiError> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())
        .map_err(DataPlaneApiError::from_s3_error)?;
    let _permit =
        try_acquire_data_plane_permit(&state).map_err(DataPlaneApiError::from_s3_error)?;
    let (_, backend) = current_primary_backend(&state)?;
    let request = ListObjectsRequest {
        container: query.container,
        prefix: query.prefix,
        limit: query.limit,
    };

    let payload = backend.list_objects(request).await?;
    record_serialized_json_bytes(&state, &payload);
    Ok(Json(payload))
}

async fn list_buckets(
    State(state): State<AppState>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(&application, S3ActionKind::ListBuckets, None, None)?;

    let read = list_containers_with_fallback(&state)
        .await
        .map_err(map_backend_error_to_s3)?;
    let containers = filter_containers_for_application(read.value, &application);

    let mut body = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
    body.push_str(&format!(
        "<ListAllMyBucketsResult xmlns=\"{S3_NS}\"><Owner><ID>ccbg</ID><DisplayName>ccbg</DisplayName></Owner><Buckets>"
    ));

    for bucket in containers {
        body.push_str(&format!(
            "<Bucket><Name>{}</Name><CreationDate>{}</CreationDate></Bucket>",
            xml_escape(&bucket.name),
            DEFAULT_TIMESTAMP
        ));
    }

    body.push_str("</Buckets></ListAllMyBucketsResult>");
    record_data_plane_bytes_out(&state, body.len() as u64);
    let mut response = xml_response(StatusCode::OK, body);
    apply_read_source_headers(response.headers_mut(), read.source);
    Ok(response)
}

async fn head_bucket(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(&application, S3ActionKind::ListObjects, Some(&bucket), None)?;

    let read_backend = resolve_bucket_read_backend(&state, &bucket)
        .await
        .map_err(|error| map_bucket_error(error, &bucket))?;

    let mut response = StatusCode::OK.into_response();
    response.headers_mut().insert(
        "x-amz-bucket-region",
        HeaderValue::from_str(&state.config.s3_region)
            .expect("configured region should be a valid header value"),
    );
    apply_read_source_headers(response.headers_mut(), read_backend.source);
    Ok(response)
}

async fn list_objects_v2(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
    Query(query): Query<ListObjectsV2Query>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::ListObjects,
        Some(&bucket),
        query.prefix.as_deref(),
    )?;

    if let Some(list_type) = &query.list_type {
        if list_type != "2" {
            return Err(S3Error::not_implemented(
                "Only ListObjectsV2 is supported in the current S3 subset.",
            ));
        }
    }

    if query.continuation_token.is_some() {
        return Err(S3Error::not_implemented(
            "continuation-token is not supported yet.",
        ));
    }

    let max_keys = query.max_keys.unwrap_or(1000).min(1000);
    let read =
        list_bucket_objects_with_fallback(&state, &bucket, query.prefix.as_deref(), max_keys)
            .await
            .map_err(|error| map_bucket_error(error, &bucket))?;
    let objects = filter_objects_for_application(read.value, &application);

    let mut body = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
    body.push_str(&format!(
        "<ListBucketResult xmlns=\"{S3_NS}\"><Name>{}</Name><Prefix>{}</Prefix><KeyCount>{}</KeyCount><MaxKeys>{}</MaxKeys><IsTruncated>false</IsTruncated>",
        xml_escape(&bucket),
        xml_escape(query.prefix.as_deref().unwrap_or("")),
        objects.len(),
        max_keys
    ));

    if let Some(delimiter) = &query.delimiter {
        body.push_str(&format!("<Delimiter>{}</Delimiter>", xml_escape(delimiter)));
    }

    for object in objects {
        body.push_str(&format!(
            "<Contents><Key>{}</Key><LastModified>{}</LastModified><ETag>{}</ETag><Size>{}</Size><StorageClass>STANDARD</StorageClass></Contents>",
            xml_escape(&object.key),
            xml_escape(object.last_modified.as_deref().unwrap_or(DEFAULT_TIMESTAMP)),
            xml_escape(&quoted_etag(object.etag.as_deref())),
            object.size,
        ));
    }

    body.push_str("</ListBucketResult>");
    record_data_plane_bytes_out(&state, body.len() as u64);
    let mut response = xml_response(StatusCode::OK, body);
    apply_read_source_headers(response.headers_mut(), read.source);
    Ok(response)
}

async fn head_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::ReadObject,
        Some(&bucket),
        Some(&key),
    )?;

    let read = head_object_with_fallback(&state, &bucket, &key)
        .await
        .map_err(|error| map_object_error(error, &bucket, &key))?;
    let object = read.value;

    let mut headers = HeaderMap::new();
    headers.insert(
        CONTENT_LENGTH,
        HeaderValue::from_str(&object.size.to_string()).expect("content length should be valid"),
    );
    headers.insert(
        CONTENT_TYPE,
        HeaderValue::from_str(
            object
                .content_type
                .as_deref()
                .unwrap_or("application/octet-stream"),
        )
        .expect("content type should be valid"),
    );
    if let Some(etag) = object.etag.as_deref() {
        headers.insert(
            ETAG,
            HeaderValue::from_str(&quoted_etag(Some(etag))).expect("etag should be valid"),
        );
    }
    if let Some(last_modified) = object.last_modified.as_deref() {
        headers.insert(
            LAST_MODIFIED,
            HeaderValue::from_str(last_modified).expect("last-modified should be valid"),
        );
    }
    apply_read_source_headers(&mut headers, read.source);

    Ok((StatusCode::OK, headers).into_response())
}

fn build_put_encryption_plan(
    state: &AppState,
    bucket: &str,
    key: &str,
    plaintext_size: u64,
    content_type: Option<String>,
    application: &S3ApplicationIdentity,
) -> Result<Option<PutEncryptionPlan>, S3Error> {
    let Some(profile) = effective_encryption_profile_for_write(
        state,
        application,
        bucket,
        key,
        content_type.as_deref(),
    )?
    else {
        return Ok(None);
    };
    let key_encryption_key =
        load_profile_encryption_key_material(state, &profile).map_err(map_backend_error_to_s3)?;
    let request = CryptoEncryptRequest {
        profile_id: profile.id.clone(),
        key_id: profile.key_id.clone(),
        algorithm_preference: profile.algorithm_preference.to_crypto(),
        chunk_plaintext_bytes: profile.chunk_plaintext_bytes,
        plaintext_size,
        logical_content_type: content_type,
    };
    let metadata = request
        .planned_metadata()
        .map_err(|error| S3Error::internal_error(error.to_string()))?;
    let logical_record = LogicalObjectRecord {
        bucket: bucket.to_string(),
        key: key.to_string(),
        encrypted: true,
        encryption_profile_id: Some(profile.id.clone()),
        algorithm: Some(metadata.algorithm.as_str().to_string()),
        key_id: Some(profile.key_id.clone()),
        key_source_kind: Some(profile.key_source_kind.as_str().to_string()),
        key_source_ref: Some(profile.key_source_ref.clone()),
        chunk_plaintext_bytes: Some(metadata.chunk_plaintext_bytes),
        plaintext_size: metadata.plaintext_size,
        stored_size: metadata.stored_size,
        logical_content_type: metadata.logical_content_type.clone(),
        updated_at_unix_ms: current_unix_ms(),
    };
    Ok(Some(PutEncryptionPlan {
        request,
        key_encryption_key,
        logical_record,
    }))
}

async fn execute_put_upload(
    state: &AppState,
    bucket: String,
    key: String,
    application: S3ApplicationIdentity,
    plaintext_size: u64,
    content_type: Option<String>,
    request_body: PreparedPutRequestBody,
    write_path: ProviderWritePathKind,
) -> Result<Response, S3Error> {
    let encryption_plan = build_put_encryption_plan(
        state,
        &bucket,
        &key,
        plaintext_size,
        content_type.clone(),
        &application,
    )?;
    let stored_size = encryption_plan
        .as_ref()
        .map(|plan| plan.logical_record.stored_size)
        .unwrap_or(plaintext_size);
    let stored_content_type = encryption_plan
        .as_ref()
        .and_then(PutEncryptionPlan::stored_content_type)
        .or(content_type.clone());
    let policy_content_type = encryption_plan
        .as_ref()
        .and_then(PutEncryptionPlan::policy_content_type)
        .or(content_type.clone());

    let (home_provider, home_backend) =
        select_home_write_provider(state, &bucket, &key, stored_size)
            .await
            .map_err(|error| S3Error::insufficient_storage(error.to_string()))?;
    if !home_backend.capabilities().streaming_put {
        ensure_object_within_in_memory_limit(&state.config, stored_size)?;
    }
    let previous_placement =
        placed_home_provider_record(state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let previous_logical =
        load_logical_object_record(state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    persist_object_home_provider(state, home_provider, &bucket, &key)
        .map_err(map_backend_error_to_s3)?;
    let logical_persist_result = match encryption_plan.as_ref() {
        Some(plan) => persist_logical_object_record(state, &plan.logical_record),
        None => delete_logical_object_record(state, &bucket, &key),
    };
    if let Err(error) = logical_persist_result {
        restore_previous_object_write_state(
            state,
            &bucket,
            &key,
            previous_placement,
            previous_logical,
        );
        return Err(map_backend_error_to_s3(error));
    }

    let write_started_at = current_unix_ms();
    state
        .provider_resource_stats
        .record_write_path(home_provider.as_str(), write_path);
    let _write_operation = state
        .provider_resource_stats
        .start_operation(home_provider.as_str(), ProviderResourceOperationKind::Write);
    let source_body = request_body.into_object_body(state, home_provider.as_str());
    let upload_body = match encryption_plan.as_ref() {
        Some(plan) => encrypt_upload(source_body, plan.request.clone(), plan.key_encryption_key)
            .map(|encrypted| encrypted.body)
            .map_err(|error| {
                restore_previous_object_write_state(
                    state,
                    &bucket,
                    &key,
                    previous_placement,
                    previous_logical.clone(),
                );
                S3Error::internal_error(error.to_string())
            })?,
        None => source_body,
    };
    let result = home_backend
        .put_object(PutObjectRequest {
            container: bucket.clone(),
            key: key.clone(),
            body: upload_body,
            size: Some(stored_size),
            content_type: stored_content_type.clone(),
            preferred_upload_part_size_bytes: None,
        })
        .await
        .map_err(|error| {
            state.provider_io_stats.record_failure(
                home_provider.as_str(),
                ProviderIoOperationKind::Write,
                &error.to_string(),
            );
            restore_previous_object_write_state(
                state,
                &bucket,
                &key,
                previous_placement,
                previous_logical.clone(),
            );
            map_backend_error_to_s3(error)
        })?;
    state.provider_io_stats.record_success_with_response(
        home_provider.as_str(),
        ProviderIoOperationKind::Write,
        current_unix_ms().saturating_sub(write_started_at),
        result.first_response_latency_ms,
        Some(stored_size),
    );

    let effective_topology = effective_topology_for_replication_put(
        state,
        Some(&application),
        &bucket,
        &key,
        stored_size,
        policy_content_type.as_deref(),
    )
    .await
    .map_err(map_backend_error_to_s3)?;
    let jobs = state.replication.enqueue_put(
        &effective_topology,
        Some(home_provider.as_str().to_string()),
        bucket.clone(),
        key.clone(),
        result.etag.clone(),
        stored_size,
        stored_content_type,
    );
    if let Err(error) = state.metadata_store.enqueue_jobs(&jobs) {
        warn!(
            bucket = %bucket,
            key = %key,
            error = %error,
            "failed to persist replication jobs after put"
        );
    }
    if !jobs.is_empty() {
        info!(
            bucket = %bucket,
            key = %key,
            queued_jobs = jobs.len(),
            "replication jobs enqueued after put"
        );
    }

    let mut response = StatusCode::OK.into_response();
    if let Some(etag) = result.etag {
        response.headers_mut().insert(
            ETAG,
            HeaderValue::from_str(&quoted_etag(Some(&etag))).expect("etag should be valid"),
        );
    }
    Ok(response)
}

fn validate_decrypted_object_metadata(
    logical: &LogicalObjectRecord,
    metadata: &object_crypto::EncryptedObjectMetadata,
) -> Result<(), S3Error> {
    if !logical.encrypted {
        return Ok(());
    }
    if logical.plaintext_size != metadata.plaintext_size {
        return Err(S3Error::internal_error(format!(
            "logical metadata plaintext size {} does not match encrypted object header {} for {}/{}",
            logical.plaintext_size, metadata.plaintext_size, logical.bucket, logical.key
        )));
    }
    if logical.stored_size < metadata.plaintext_size {
        return Err(S3Error::internal_error(format!(
            "logical metadata stored size {} is smaller than plaintext size {} for {}/{}",
            logical.stored_size, metadata.plaintext_size, logical.bucket, logical.key
        )));
    }
    if logical.algorithm.as_deref() != Some(metadata.algorithm.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata algorithm {:?} does not match encrypted object header {} for {}/{}",
            logical.algorithm,
            metadata.algorithm.as_str(),
            logical.bucket,
            logical.key
        )));
    }
    if logical.key_id.as_deref() != Some(metadata.key_id.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata key_id {:?} does not match encrypted object header {} for {}/{}",
            logical.key_id, metadata.key_id, logical.bucket, logical.key
        )));
    }
    if logical.encryption_profile_id.as_deref() != Some(metadata.profile_id.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata profile {:?} does not match encrypted object header {} for {}/{}",
            logical.encryption_profile_id, metadata.profile_id, logical.bucket, logical.key
        )));
    }
    if logical.chunk_plaintext_bytes != Some(metadata.chunk_plaintext_bytes) {
        return Err(S3Error::internal_error(format!(
            "logical metadata chunk size {:?} does not match encrypted object header {} for {}/{}",
            logical.chunk_plaintext_bytes,
            metadata.chunk_plaintext_bytes,
            logical.bucket,
            logical.key
        )));
    }
    if logical.logical_content_type.as_deref() != metadata.logical_content_type.as_deref() {
        return Err(S3Error::internal_error(format!(
            "logical metadata content-type {:?} does not match encrypted object header {:?} for {}/{}",
            logical.logical_content_type,
            metadata.logical_content_type,
            logical.bucket,
            logical.key
        )));
    }
    Ok(())
}

async fn get_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::ReadObject,
        Some(&bucket),
        Some(&key),
    )?;

    let resolved = resolve_object_read(&state, &bucket, &key)
        .await
        .map_err(|error| map_object_error(error, &bucket, &key))?;
    if !resolved.backend.capabilities().streaming_get {
        ensure_object_within_in_memory_limit(&state.config, resolved.object.size)?;
    }
    let read_started_at = current_unix_ms();
    let read_usage = state.provider_resource_stats.start_operation(
        resolved.source.provider.as_str(),
        ProviderResourceOperationKind::Read,
    );
    let object = resolved
        .backend
        .get_object(&bucket, &key)
        .await
        .map_err(|error| {
            state.provider_io_stats.record_failure(
                resolved.source.provider.as_str(),
                ProviderIoOperationKind::Read,
                &error.to_string(),
            );
            map_object_error(error, &bucket, &key)
        })?;
    let observed_body = observe_provider_read_body(
        state.provider_io_stats.clone(),
        resolved.source.provider.as_str(),
        read_started_at,
        object.info.size,
        object.first_response_latency_ms,
        object.body,
        read_usage,
    );
    let logical =
        load_logical_object_record(&state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let (response_object, response_body) = if let Some(logical) = logical.as_ref() {
        if logical.encrypted {
            let key_source_kind = logical.key_source_kind.as_deref().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_source_kind metadata"
                ))
            })?;
            let key_source_kind = match key_source_kind {
                "env_var" => EncryptionKeySourceKind::EnvVar,
                "file_path" => EncryptionKeySourceKind::FilePath,
                "external_kms" => EncryptionKeySourceKind::ExternalKms,
                "gateway_managed" => EncryptionKeySourceKind::GatewayManaged,
                other => {
                    return Err(S3Error::internal_error(format!(
                        "encrypted object {bucket}/{key} has unknown key_source_kind {other}"
                    )));
                }
            };
            let key_source_ref = logical.key_source_ref.clone().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_source_ref metadata"
                ))
            })?;
            let key_id = logical.key_id.clone().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_id metadata"
                ))
            })?;
            let profile = EncryptionProfile {
                id: logical
                    .encryption_profile_id
                    .clone()
                    .unwrap_or_else(|| "restored".to_string()),
                label: None,
                enabled: true,
                algorithm_preference: EncryptionAlgorithmPreference::Auto,
                chunk_plaintext_bytes: logical.chunk_plaintext_bytes.unwrap_or_default(),
                key_id,
                key_source_kind,
                key_source_ref,
                notes: None,
            };
            let key_encryption_key = load_profile_encryption_key_material(&state, &profile)
                .map_err(map_backend_error_to_s3)?;
            let prepared = prepare_decrypt_download(observed_body, key_encryption_key)
                .await
                .map_err(|error| S3Error::internal_error(error.to_string()))?;
            validate_decrypted_object_metadata(logical, &prepared.metadata)?;
            (
                public_object_info(object.info, Some(logical)),
                prepared.body,
            )
        } else {
            (
                public_object_info(object.info, Some(logical)),
                observed_body,
            )
        }
    } else {
        (object.info, observed_body)
    };

    let mut response_headers = HeaderMap::new();
    response_headers.insert(
        CONTENT_LENGTH,
        HeaderValue::from_str(&response_object.size.to_string())
            .expect("content length should be valid"),
    );
    response_headers.insert(
        CONTENT_TYPE,
        HeaderValue::from_str(
            response_object
                .content_type
                .as_deref()
                .unwrap_or("application/octet-stream"),
        )
        .expect("content type should be valid"),
    );
    if let Some(etag) = response_object.etag.as_deref() {
        response_headers.insert(
            ETAG,
            HeaderValue::from_str(&quoted_etag(Some(etag))).expect("etag should be valid"),
        );
    }
    apply_read_source_headers(&mut response_headers, resolved.source);

    // Keep the permit alive until the response body stream is fully consumed.
    let data_plane_stats = state.data_plane_stats.clone();
    let body_stream = futures_util::stream::unfold(
        (permit, response_body.into_stream(), data_plane_stats),
        |(permit, mut inner, data_plane_stats)| async move {
            inner.next().await.map(|item| {
                let item = item.map(|chunk| {
                    data_plane_stats.record_bytes_out(chunk.len() as u64);
                    chunk
                });
                (
                    item.map_err(std::io::Error::other),
                    (permit, inner, data_plane_stats),
                )
            })
        },
    );
    Ok((
        StatusCode::OK,
        response_headers,
        Body::from_stream(body_stream),
    )
        .into_response())
}

async fn put_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let content_length = headers
        .get(CONTENT_LENGTH)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<u64>().ok());
    let payload_hash = headers
        .get("x-amz-content-sha256")
        .and_then(|value| value.to_str().ok())
        .ok_or_else(|| S3Error::access_denied("Missing x-amz-content-sha256 header."))?
        .to_string();
    let content_type = headers
        .get(CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(ToString::to_string);

    let (application, body_len, request_body, write_path) = if payload_hash == "UNSIGNED-PAYLOAD" {
        let application = authorize_s3(&state, &method, &uri, &headers, None)?;
        ensure_s3_application_permission(
            &application,
            S3ActionKind::WriteObject,
            Some(&bucket),
            Some(&key),
        )?;
        let body_len = content_length.ok_or_else(|| {
            S3Error::access_denied(
                "UNSIGNED-PAYLOAD uploads must include a valid Content-Length header.",
            )
        })?;
        let request_body = PreparedPutRequestBody::Plain(ObjectBody::from_stream(
            body.into_data_stream()
                .map_ok({
                    let data_plane_stats = state.data_plane_stats.clone();
                    move |chunk| {
                        data_plane_stats.record_bytes_in(chunk.len() as u64);
                        chunk
                    }
                })
                .map_err(|error| BlobError::BodyStream(error.to_string())),
        ));
        (
            application,
            body_len,
            request_body,
            ProviderWritePathKind::Streaming,
        )
    } else {
        let use_in_memory_body = content_length
            .map(|length| length <= state.config.max_in_memory_object_bytes as u64)
            .unwrap_or(state.config.max_spooled_object_bytes == 0);
        if use_in_memory_body {
            let body = to_bytes(body, state.config.max_in_memory_object_bytes)
                .await
                .map_err(|error| {
                    S3Error::entity_too_large(format!(
                        "request body exceeds in-memory limit: {error}"
                    ))
                })?;
            record_data_plane_bytes_in(&state, body.len() as u64);
            let application = authorize_s3(&state, &method, &uri, &headers, Some(&body))?;
            ensure_s3_application_permission(
                &application,
                S3ActionKind::WriteObject,
                Some(&bucket),
                Some(&key),
            )?;
            ensure_object_within_in_memory_limit(&state.config, body.len() as u64)?;
            (
                application,
                body.len() as u64,
                PreparedPutRequestBody::Plain(body.into()),
                ProviderWritePathKind::InMemory,
            )
        } else {
            let spooled = spool_signed_request_body(&state, body, content_length).await?;
            let application = authorize_s3_with_verified_payload_hash(
                &state,
                &method,
                &uri,
                &headers,
                &spooled.sha256_hex,
            )?;
            ensure_s3_application_permission(
                &application,
                S3ActionKind::WriteObject,
                Some(&bucket),
                Some(&key),
            )?;
            (
                application,
                spooled.size,
                PreparedPutRequestBody::Spooled(spooled),
                ProviderWritePathKind::Spooled,
            )
        }
    };

    execute_put_upload(
        &state,
        bucket,
        key,
        application,
        body_len,
        content_type,
        request_body,
        write_path,
    )
    .await
}

async fn delete_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::DeleteObject,
        Some(&bucket),
        Some(&key),
    )?;
    let home_provider = persisted_or_primary_home_provider(&state, &bucket, &key)
        .map_err(map_backend_error_to_s3)?;
    let home_backend =
        backend_for_provider(&state, home_provider).map_err(map_backend_error_to_s3)?;

    home_backend
        .delete_object(&bucket, &key)
        .await
        .map_err(|error| map_object_error(error, &bucket, &key))?;

    delete_persisted_object_home_provider(&state, &bucket, &key)
        .map_err(map_backend_error_to_s3)?;
    delete_logical_object_record(&state, &bucket, &key).map_err(map_backend_error_to_s3)?;

    let effective_topology =
        effective_topology_for_replication(&state, ReplicationOperation::Delete, &bucket, &key)
            .map_err(map_backend_error_to_s3)?;
    let jobs = state.replication.enqueue_delete(
        &effective_topology,
        Some(home_provider.as_str().to_string()),
        bucket.clone(),
        key.clone(),
    );
    if let Err(error) = state.metadata_store.enqueue_jobs(&jobs) {
        warn!(
            bucket = %bucket,
            key = %key,
            error = %error,
            "failed to persist replication jobs after delete"
        );
    }
    if !jobs.is_empty() {
        info!(
            bucket = %bucket,
            key = %key,
            queued_jobs = jobs.len(),
            "replication jobs enqueued after delete"
        );
    }

    Ok(StatusCode::NO_CONTENT.into_response())
}

fn authorize_s3(
    state: &AppState,
    method: &Method,
    uri: &Uri,
    headers: &HeaderMap,
    body: Option<&[u8]>,
) -> Result<S3ApplicationIdentity, S3Error> {
    let payload_hash = match body {
        Some(bytes) => sha256_hex(bytes),
        None => sha256_hex(&[]),
    };
    authorize_s3_with_verified_payload_hash(state, method, uri, headers, &payload_hash)
}

fn authorize_s3_with_verified_payload_hash(
    state: &AppState,
    method: &Method,
    uri: &Uri,
    headers: &HeaderMap,
    verified_payload_hash: &str,
) -> Result<S3ApplicationIdentity, S3Error> {
    let authorization = headers
        .get(AUTHORIZATION)
        .ok_or_else(|| S3Error::access_denied("Missing Authorization header."))?
        .to_str()
        .map_err(|_| S3Error::access_denied("Authorization header is not valid UTF-8."))?;

    let parsed = parse_authorization_header(authorization)?;

    let (application, secret_access_key) = resolve_s3_application(state, &parsed.access_key)
        .ok_or_else(S3Error::invalid_access_key)?;

    if parsed.region != state.config.s3_region {
        return Err(S3Error::signature_mismatch(format!(
            "Credential should use region {}.",
            state.config.s3_region
        )));
    }

    if parsed.service != "s3" {
        return Err(S3Error::signature_mismatch(
            "Credential scope service must be s3.",
        ));
    }

    let amz_date = headers
        .get("x-amz-date")
        .ok_or_else(|| S3Error::access_denied("Missing x-amz-date header."))?
        .to_str()
        .map_err(|_| S3Error::access_denied("x-amz-date header is not valid UTF-8."))?;

    let payload_hash = headers
        .get("x-amz-content-sha256")
        .ok_or_else(|| S3Error::access_denied("Missing x-amz-content-sha256 header."))?
        .to_str()
        .map_err(|_| S3Error::access_denied("x-amz-content-sha256 header is not valid UTF-8."))?;

    if payload_hash != "UNSIGNED-PAYLOAD" {
        if verified_payload_hash != payload_hash {
            return Err(S3Error::signature_mismatch(
                "x-amz-content-sha256 does not match the request body.",
            ));
        }
    }

    let canonical_request = format!(
        "{}\n{}\n{}\n{}\n{}\n{}",
        method.as_str(),
        canonical_uri(uri.path()),
        canonical_query_string(uri.query()),
        canonical_headers(headers, &parsed.signed_headers)?,
        parsed.signed_headers.join(";"),
        payload_hash
    );

    let string_to_sign = format!(
        "AWS4-HMAC-SHA256\n{}\n{}/{}/{}/aws4_request\n{}",
        amz_date,
        parsed.date,
        parsed.region,
        parsed.service,
        sha256_hex(canonical_request.as_bytes())
    );

    let expected_signature = sign_v4(
        &secret_access_key,
        &parsed.date,
        &parsed.region,
        &parsed.service,
        &string_to_sign,
    );

    if expected_signature != parsed.signature {
        return Err(S3Error::signature_mismatch(
            "The request signature we calculated does not match the signature you provided.",
        ));
    }

    Ok(application)
}

fn parse_authorization_header(value: &str) -> Result<ParsedAuthorization, S3Error> {
    let Some(parameters) = value.strip_prefix("AWS4-HMAC-SHA256 ") else {
        return Err(S3Error::access_denied(
            "Only AWS4-HMAC-SHA256 Authorization is supported.",
        ));
    };

    let mut entries = BTreeMap::new();
    for item in parameters.split(',') {
        let trimmed = item.trim();
        let Some((key, value)) = trimmed.split_once('=') else {
            return Err(S3Error::signature_mismatch(
                "Authorization header is malformed.",
            ));
        };
        entries.insert(key.to_string(), value.to_string());
    }

    let credential = entries
        .get("Credential")
        .ok_or_else(|| S3Error::signature_mismatch("Credential is missing."))?;
    let signed_headers = entries
        .get("SignedHeaders")
        .ok_or_else(|| S3Error::signature_mismatch("SignedHeaders is missing."))?;
    let signature = entries
        .get("Signature")
        .ok_or_else(|| S3Error::signature_mismatch("Signature is missing."))?;

    let parts: Vec<_> = credential.split('/').collect();
    if parts.len() != 5 || parts[4] != "aws4_request" {
        return Err(S3Error::signature_mismatch(
            "Credential scope is malformed.",
        ));
    }

    Ok(ParsedAuthorization {
        access_key: parts[0].to_string(),
        date: parts[1].to_string(),
        region: parts[2].to_string(),
        service: parts[3].to_string(),
        signed_headers: signed_headers.split(';').map(ToString::to_string).collect(),
        signature: signature.to_string(),
    })
}

fn canonical_uri(path: &str) -> String {
    if path.is_empty() {
        "/".to_string()
    } else {
        path.to_string()
    }
}

fn canonical_query_string(query: Option<&str>) -> String {
    let Some(query) = query else {
        return String::new();
    };

    let mut pairs: Vec<(String, String)> = query
        .split('&')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut segments = part.splitn(2, '=');
            (
                segments.next().unwrap_or_default().to_string(),
                segments.next().unwrap_or_default().to_string(),
            )
        })
        .collect();

    pairs.sort();

    pairs
        .into_iter()
        .map(|(key, value)| format!("{key}={value}"))
        .collect::<Vec<_>>()
        .join("&")
}

fn canonical_headers(headers: &HeaderMap, signed_headers: &[String]) -> Result<String, S3Error> {
    let mut parts = Vec::with_capacity(signed_headers.len());

    for name in signed_headers {
        let value = if name == "host" {
            headers
                .get(HOST)
                .ok_or_else(|| S3Error::signature_mismatch("Signed host header is missing."))?
        } else {
            headers.get(name.as_str()).ok_or_else(|| {
                S3Error::signature_mismatch(format!("Signed header {name} is missing."))
            })?
        };

        let normalized = normalize_header_value(
            value
                .to_str()
                .map_err(|_| S3Error::signature_mismatch("Signed header is not valid UTF-8."))?,
        );
        parts.push(format!("{name}:{normalized}\n"));
    }

    Ok(parts.concat())
}

fn normalize_header_value(value: &str) -> String {
    value.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn sign_v4(secret: &str, date: &str, region: &str, service: &str, string_to_sign: &str) -> String {
    let date_key = hmac_sha256(format!("AWS4{secret}").as_bytes(), date.as_bytes());
    let region_key = hmac_sha256(&date_key, region.as_bytes());
    let service_key = hmac_sha256(&region_key, service.as_bytes());
    let signing_key = hmac_sha256(&service_key, b"aws4_request");
    hex::encode(hmac_sha256(&signing_key, string_to_sign.as_bytes()))
}

fn hmac_sha256(key: &[u8], data: &[u8]) -> Vec<u8> {
    let mut mac = HmacSha256::new_from_slice(key).expect("hmac key should be valid");
    mac.update(data);
    mac.finalize().into_bytes().to_vec()
}

fn sha256_hex(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    hex::encode(hasher.finalize())
}

fn map_backend_error_to_s3(error: BlobError) -> S3Error {
    match error {
        BlobError::Configuration(message) => S3Error::internal_error(message),
        BlobError::Upstream(message) => S3Error::internal_error(message),
        BlobError::BodyStream(message) => S3Error::internal_error(message),
        BlobError::InteractiveInputRequired(message) => S3Error::internal_error(message),
        BlobError::NotImplemented(message) => S3Error::not_implemented(message),
        BlobError::NotFound(message) => S3Error::internal_error(message),
    }
}

fn map_bucket_error(error: BlobError, bucket: &str) -> S3Error {
    match error {
        BlobError::NotFound(_) => S3Error::no_such_bucket(bucket),
        other => map_backend_error_to_s3(other),
    }
}

fn map_object_error(error: BlobError, bucket: &str, key: &str) -> S3Error {
    match error {
        BlobError::NotFound(_) => S3Error::no_such_key(bucket, key),
        other => map_backend_error_to_s3(other),
    }
}

fn xml_escape(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn quoted_etag(etag: Option<&str>) -> String {
    format!("\"{}\"", etag.unwrap_or(""))
}

fn xml_response(status: StatusCode, body: String) -> Response {
    let mut headers = HeaderMap::new();
    headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/xml"));
    headers.insert("x-amz-request-id", HeaderValue::from_static(REQUEST_ID));

    (status, headers, body).into_response()
}

async fn shutdown_signal() {
    let _ = tokio::signal::ctrl_c().await;
}

