    #[derive(Debug, Clone)]
    struct LimitProbeUploadAttempt {
        key: String,
        declared_size: Option<u64>,
        preferred_upload_part_size_bytes: Option<u64>,
        max_body_chunk_bytes: u64,
        received_bytes: u64,
    }

    #[derive(Debug, Clone, Copy)]
    struct LimitProbeReadPlan {
        chunk_size_bytes: u64,
        chunk_delay: Duration,
    }

    struct LimitProbeRecordingBackend {
        capabilities: BackendCapabilities,
        max_upload_bytes: u64,
        max_download_bytes: u64,
        max_stream_chunk_bytes: u64,
        read_plan: Option<LimitProbeReadPlan>,
        attempts: Mutex<Vec<LimitProbeUploadAttempt>>,
        objects: Mutex<BTreeMap<String, u64>>,
    }

    impl LimitProbeRecordingBackend {
        fn new(
            upload_part_size_bytes: u64,
            max_upload_bytes: u64,
            max_download_bytes: u64,
            max_stream_chunk_bytes: u64,
        ) -> Self {
            Self {
                capabilities: BackendCapabilities {
                    read: true,
                    write: true,
                    delete: true,
                    multipart_upload: false,
                    streaming_get: true,
                    streaming_put: true,
                    max_single_upload_bytes: None,
                    max_single_download_bytes: None,
                    upload_part_size_bytes: Some(upload_part_size_bytes),
                },
                max_upload_bytes,
                max_download_bytes,
                max_stream_chunk_bytes,
                read_plan: None,
                attempts: Mutex::new(Vec::new()),
                objects: Mutex::new(BTreeMap::new()),
            }
        }

        fn with_read_plan(mut self, chunk_size_bytes: u64, chunk_delay: Duration) -> Self {
            self.read_plan = Some(LimitProbeReadPlan {
                chunk_size_bytes: chunk_size_bytes.max(1),
                chunk_delay,
            });
            self
        }

        fn attempts(&self) -> Vec<LimitProbeUploadAttempt> {
            self.attempts
                .lock()
                .expect("limit probe attempt list poisoned")
                .clone()
        }
    }

    #[async_trait::async_trait]
    impl BlobBackend for LimitProbeRecordingBackend {
        fn name(&self) -> &'static str {
            "limit-probe-recording"
        }

        fn capabilities(&self) -> BackendCapabilities {
            self.capabilities.clone()
        }

        async fn health(&self) -> Result<ServiceHealth, BlobError> {
            Ok(ServiceHealth {
                backend: self.name().to_string(),
                status: HealthStatus::Healthy,
                capabilities: self.capabilities(),
                scopes: Vec::new(),
                notes: vec!["limit probe recording backend".to_string()],
            })
        }

        async fn list_containers(&self) -> Result<Vec<ContainerInfo>, BlobError> {
            Ok(vec![ContainerInfo {
                name: "root".to_string(),
                object_count: Some(
                    self.objects
                        .lock()
                        .expect("limit probe object map poisoned")
                        .len() as u64,
                ),
            }])
        }

        async fn list_objects(
            &self,
            request: ListObjectsRequest,
        ) -> Result<Vec<ObjectInfo>, BlobError> {
            let prefix = request.prefix.unwrap_or_default();
            let limit = request.limit.unwrap_or(usize::MAX);
            Ok(self
                .objects
                .lock()
                .expect("limit probe object map poisoned")
                .iter()
                .filter(|(key, _)| key.starts_with(&prefix))
                .take(limit)
                .map(|(key, size)| ObjectInfo {
                    key: key.clone(),
                    size: *size,
                    etag: None,
                    content_type: Some("application/octet-stream".to_string()),
                    last_modified: None,
                })
                .collect())
        }

        async fn get_object(
            &self,
            _container: &str,
            key: &str,
        ) -> Result<ObjectPayload, BlobError> {
            let size = *self
                .objects
                .lock()
                .expect("limit probe object map poisoned")
                .get(key)
                .ok_or_else(|| BlobError::NotFound(format!("object not found: {key}")))?;
            if size > self.max_download_bytes {
                return Err(BlobError::Upstream(format!(
                    "download size limit exceeded: {size}"
                )));
            }
            let body = if let Some(read_plan) = self.read_plan {
                let chunk_size_bytes = read_plan.chunk_size_bytes;
                let chunk_delay = read_plan.chunk_delay;
                ObjectBody::from_stream(stream::try_unfold(size, move |remaining| async move {
                    if remaining == 0 {
                        return Ok(None);
                    }
                    if !chunk_delay.is_zero() {
                        sleep(chunk_delay).await;
                    }
                    let next_len = remaining.min(chunk_size_bytes) as usize;
                    Ok(Some((
                        Bytes::from(vec![0u8; next_len]),
                        remaining.saturating_sub(next_len as u64),
                    )))
                }))
            } else {
                zero_probe_body(size, 3)
            };
            Ok(ObjectPayload {
                info: ObjectInfo {
                    key: key.to_string(),
                    size,
                    etag: None,
                    content_type: Some("application/octet-stream".to_string()),
                    last_modified: None,
                },
                body,
                first_response_latency_ms: Some(2),
            })
        }

        async fn put_object(
            &self,
            request: PutObjectRequest,
        ) -> Result<blob_core::PutObjectResult, BlobError> {
            if request
                .size
                .is_some_and(|size| size > self.max_upload_bytes)
            {
                return Err(BlobError::Upstream(format!(
                    "file size limit exceeded: {}",
                    request.size.unwrap_or_default()
                )));
            }

            let mut stream = request.body.into_stream();
            let mut received_bytes = 0u64;
            let mut max_body_chunk_bytes = 0u64;
            while let Some(chunk) = stream.next().await {
                let chunk = chunk?;
                let chunk_len = chunk.len() as u64;
                max_body_chunk_bytes = max_body_chunk_bytes.max(chunk_len);
                if chunk_len > self.max_stream_chunk_bytes {
                    self.attempts
                        .lock()
                        .expect("limit probe attempt list poisoned")
                        .push(LimitProbeUploadAttempt {
                            key: request.key.clone(),
                            declared_size: request.size,
                            preferred_upload_part_size_bytes: request
                                .preferred_upload_part_size_bytes,
                            max_body_chunk_bytes,
                            received_bytes,
                        });
                    return Err(BlobError::Upstream(format!("chunk too large: {chunk_len}")));
                }
                received_bytes = received_bytes.saturating_add(chunk_len);
            }
            if request.size.is_some_and(|size| size != received_bytes) {
                return Err(BlobError::BodyStream(format!(
                    "declared size {:?} did not match received {received_bytes}",
                    request.size
                )));
            }
            self.attempts
                .lock()
                .expect("limit probe attempt list poisoned")
                .push(LimitProbeUploadAttempt {
                    key: request.key.clone(),
                    declared_size: request.size,
                    preferred_upload_part_size_bytes: request.preferred_upload_part_size_bytes,
                    max_body_chunk_bytes,
                    received_bytes,
                });
            self.objects
                .lock()
                .expect("limit probe object map poisoned")
                .insert(request.key, received_bytes);
            Ok(blob_core::PutObjectResult {
                etag: None,
                first_response_latency_ms: Some(1),
            })
        }

        async fn delete_object(&self, _container: &str, key: &str) -> Result<(), BlobError> {
            if self
                .objects
                .lock()
                .expect("limit probe object map poisoned")
                .remove(key)
                .is_some()
            {
                Ok(())
            } else {
                Err(BlobError::NotFound(format!("object not found: {key}")))
            }
        }
    }

    #[derive(Debug, Default)]
    struct RecordingBrowserFlowSession {
        actions: Arc<Mutex<Vec<String>>>,
    }

    #[derive(Debug, Clone, Default)]
    struct RecordingBrowserFlowOutputReader {
        values: Arc<Mutex<HashMap<String, serde_json::Value>>>,
        request_headers: Arc<Mutex<HashMap<String, String>>>,
        request_fields: Arc<Mutex<HashMap<String, String>>>,
        current_url: Arc<Mutex<Option<String>>>,
    }

    impl RecordingBrowserFlowSession {
        fn actions(&self) -> Vec<String> {
            self.actions
                .lock()
                .expect("recording browser flow session poisoned")
                .clone()
        }

        fn record(&self, action: String) {
            self.actions
                .lock()
                .expect("recording browser flow session poisoned")
                .push(action);
        }
    }

    #[async_trait::async_trait]
    impl BrowserFlowOutputReader for RecordingBrowserFlowOutputReader {
        async fn evaluate_output_script(
            &self,
            expression: &str,
            _frame_selector: Option<&str>,
        ) -> Result<serde_json::Value, BlobError> {
            self.values
                .lock()
                .expect("recording browser flow output reader poisoned")
                .get(expression)
                .cloned()
                .ok_or_else(|| {
                    BlobError::NotFound(format!(
                        "recording browser flow output not found for expression: {expression}"
                    ))
                })
        }

        async fn read_dom_text(
            &self,
            expression: &str,
            _frame_selector: Option<&str>,
        ) -> Result<Option<String>, BlobError> {
            match self
                .values
                .lock()
                .expect("recording browser flow output reader poisoned")
                .get(expression)
                .cloned()
            {
                Some(serde_json::Value::String(value)) => Ok(Some(value)),
                Some(serde_json::Value::Null) | None => Ok(None),
                Some(value) => Ok(Some(value.to_string())),
            }
        }

        async fn read_current_url(
            &self,
            _frame_selector: Option<&str>,
        ) -> Result<Option<String>, BlobError> {
            Ok(self
                .current_url
                .lock()
                .expect("recording browser flow output reader poisoned")
                .clone())
        }

        async fn read_request_header(
            &self,
            request: &blob_core::BrowserFlowRequest,
            header_name: &str,
        ) -> Result<Option<String>, BlobError> {
            let key = format!("{}:{}", request.id, header_name.trim().to_ascii_lowercase());
            Ok(self
                .request_headers
                .lock()
                .expect("recording browser flow output reader poisoned")
                .get(&key)
                .cloned())
        }

        async fn read_request_field(
            &self,
            request: &blob_core::BrowserFlowRequest,
            field_name: &str,
        ) -> Result<Option<String>, BlobError> {
            let key = format!("{}:{}", request.id, field_name.trim());
            Ok(self
                .request_fields
                .lock()
                .expect("recording browser flow output reader poisoned")
                .get(&key)
                .cloned())
        }
    }

    #[async_trait::async_trait]
    impl BrowserFlowSession for RecordingBrowserFlowSession {
        async fn navigate(&self, url: &str) -> Result<(), BlobError> {
            self.record(format!("navigate:{url}"));
            Ok(())
        }

        async fn click(&self, element: &BrowserFlowElement) -> Result<(), BlobError> {
            self.record(format!("click:{}", element.id));
            Ok(())
        }

        async fn set_input(
            &self,
            element: &BrowserFlowElement,
            value: &str,
            dispatch_events: &[String],
        ) -> Result<(), BlobError> {
            self.record(format!(
                "set_input:{}:{}:{}",
                element.id,
                value,
                dispatch_events.join(",")
            ));
            Ok(())
        }

        async fn invoke_operation(
            &self,
            operation: &BrowserFlowOperation,
        ) -> Result<(), BlobError> {
            self.record(format!("invoke_operation:{}", operation.id));
            Ok(())
        }

        async fn set_files(
            &self,
            element: &BrowserFlowElement,
            paths: &[String],
        ) -> Result<(), BlobError> {
            self.record(format!("set_files:{}:{}", element.id, paths.join("|")));
            Ok(())
        }

        async fn dispatch_events(
            &self,
            element: &BrowserFlowElement,
            events: &[String],
        ) -> Result<(), BlobError> {
            self.record(format!(
                "dispatch_events:{}:{}",
                element.id,
                events.join(",")
            ));
            Ok(())
        }

        async fn validate_visual_layout(
            &self,
            request: &BrowserFlowVisualLayoutValidationRequest,
        ) -> Result<(), BlobError> {
            self.record(format!(
                "validate_visual_layout:{}",
                request
                    .targets
                    .iter()
                    .map(|target| format!("{}={}", target.role, target.element.id))
                    .collect::<Vec<_>>()
                    .join("|")
            ));
            Ok(())
        }

        async fn solve_visual_captcha(
            &self,
            request: &BrowserFlowVisualCaptchaRequest,
        ) -> Result<(), BlobError> {
            match request.manual_value.as_deref() {
                Some(value) => {
                    self.record(format!(
                        "solve_visual_captcha:{}:{}:{}",
                        request.image_element.id, request.input_element.id, value
                    ));
                    Ok(())
                }
                None if request.optional => Err(BlobError::NotFound(format!(
                    "optional captcha not present: {}",
                    request.image_element.id
                ))),
                None => Err(BlobError::InteractiveInputRequired(
                    request.input_id.clone(),
                )),
            }
        }

        async fn wait_for_request(
            &self,
            request: &BrowserFlowRequest,
            timeout_ms: Option<u64>,
        ) -> Result<(), BlobError> {
            self.record(format!(
                "wait_for_request:{}:{}",
                request.id,
                timeout_ms.unwrap_or_default()
            ));
            Ok(())
        }

        async fn wait_for_page(
            &self,
            page: &BrowserFlowPage,
            timeout_ms: Option<u64>,
        ) -> Result<(), BlobError> {
            self.record(format!(
                "wait_for_page:{}:{}",
                page.id,
                timeout_ms.unwrap_or_default()
            ));
            Ok(())
        }

        async fn wait(&self, duration_ms: u64) -> Result<(), BlobError> {
            self.record(format!("wait:{duration_ms}"));
            Ok(())
        }
    }

    #[async_trait::async_trait]
    impl BlobBackend for FlakyWriteBackend {
        fn name(&self) -> &'static str {
            self.name
        }

        fn capabilities(&self) -> BackendCapabilities {
            BackendCapabilities {
                read: true,
                write: true,
                delete: true,
                multipart_upload: false,
                streaming_get: false,
                streaming_put: false,
                max_single_upload_bytes: None,
                max_single_download_bytes: None,
                upload_part_size_bytes: None,
            }
        }

        async fn health(&self) -> Result<ServiceHealth, BlobError> {
            Ok(ServiceHealth {
                backend: self.name().to_string(),
                status: HealthStatus::Healthy,
                capabilities: self.capabilities(),
                scopes: Vec::new(),
                notes: vec!["test flaky backend".to_string()],
            })
        }

        async fn list_containers(&self) -> Result<Vec<ContainerInfo>, BlobError> {
            self.inner.list_containers().await
        }

        async fn list_objects(
            &self,
            request: ListObjectsRequest,
        ) -> Result<Vec<ObjectInfo>, BlobError> {
            self.inner.list_objects(request).await
        }

        async fn get_object(
            &self,
            container: &str,
            key: &str,
        ) -> Result<blob_core::ObjectPayload, BlobError> {
            self.inner.get_object(container, key).await
        }

        async fn put_object(
            &self,
            request: PutObjectRequest,
        ) -> Result<blob_core::PutObjectResult, BlobError> {
            self.maybe_fail_write()?;
            self.inner.put_object(request).await
        }

        async fn delete_object(&self, container: &str, key: &str) -> Result<(), BlobError> {
            self.inner.delete_object(container, key).await
        }
    }

