    fn record_replication_state(
        state: &AppState,
        provider: ProviderId,
        operation: ReplicationOperation,
        status: ReplicationStatus,
        bucket: &str,
        key: &str,
        size: Option<u64>,
        content_type: Option<&str>,
    ) {
        let job_id = state
            .metadata_store
            .max_job_id()
            .expect("max job id should load")
            .unwrap_or(0)
            .saturating_add(1);

        let job = ReplicationJob {
            job_id,
            target: provider.as_str().to_string(),
            source_provider: Some(ProviderId::Stub.as_str().to_string()),
            operation,
            object: replication_engine::ReplicationObjectRef {
                bucket: bucket.to_string(),
                key: key.to_string(),
                etag: None,
                size,
                content_type: content_type.map(ToString::to_string),
            },
            status: ReplicationStatus::Pending,
            attempts: 0,
            enqueued_at_unix_ms: 1,
            next_attempt_at_unix_ms: None,
            last_error: None,
        };

        state
            .metadata_store
            .enqueue_jobs(&[job])
            .expect("job should persist");

        if !matches!(status, ReplicationStatus::Pending) {
            state
                .metadata_store
                .mark_job_status(job_id, status, 1, None)
                .expect("job status should update");
        }
    }

    fn signed_headers(
        config: &AppConfig,
        method: &Method,
        uri: &Uri,
        body: &[u8],
        extra_headers: &[(&str, &str)],
    ) -> HeaderMap {
        signed_headers_for_application(
            config,
            &config.s3_access_key_id,
            &config.s3_secret_access_key,
            method,
            uri,
            body,
            extra_headers,
        )
    }

    fn signed_headers_for_application(
        config: &AppConfig,
        access_key_id: &str,
        secret_access_key: &str,
        method: &Method,
        uri: &Uri,
        body: &[u8],
        extra_headers: &[(&str, &str)],
    ) -> HeaderMap {
        let amz_date = "20260424T120000Z";
        let short_date = "20260424";
        let payload_hash = sha256_hex(body);

        let mut headers = HeaderMap::new();
        headers.insert(HOST, HeaderValue::from_static("127.0.0.1:61080"));
        headers.insert("x-amz-date", HeaderValue::from_static("20260424T120000Z"));
        headers.insert(
            "x-amz-content-sha256",
            HeaderValue::from_str(&payload_hash).expect("payload hash should be valid"),
        );

        let mut signed_headers = vec![
            "host".to_string(),
            "x-amz-content-sha256".to_string(),
            "x-amz-date".to_string(),
        ];

        for (name, value) in extra_headers {
            let header_name =
                axum::http::HeaderName::from_bytes(name.as_bytes()).expect("header name is valid");
            headers.insert(
                header_name,
                HeaderValue::from_str(value).expect("extra header should be valid"),
            );
            signed_headers.push(name.to_ascii_lowercase());
        }

        signed_headers.sort();
        signed_headers.dedup();

        let canonical_request = format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            method.as_str(),
            canonical_uri(uri.path()),
            canonical_query_string(uri.query()),
            canonical_headers(&headers, &signed_headers)
                .expect("canonical headers should build in tests"),
            signed_headers.join(";"),
            payload_hash
        );

        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{}\n{}/{}/s3/aws4_request\n{}",
            amz_date,
            short_date,
            config.s3_region,
            sha256_hex(canonical_request.as_bytes())
        );

        let signature = sign_v4(
            secret_access_key,
            short_date,
            &config.s3_region,
            "s3",
            &string_to_sign,
        );
        let authorization = format!(
            "AWS4-HMAC-SHA256 Credential={}/{}/{}/s3/aws4_request, SignedHeaders={}, Signature={}",
            access_key_id,
            short_date,
            config.s3_region,
            signed_headers.join(";"),
            signature
        );

        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&authorization).expect("authorization should be valid"),
        );

        headers
    }

    fn unsigned_payload_headers(
        config: &AppConfig,
        method: &Method,
        uri: &Uri,
        content_length: u64,
        extra_headers: &[(&str, &str)],
    ) -> HeaderMap {
        let amz_date = "20260424T120000Z";
        let short_date = "20260424";
        let payload_hash = "UNSIGNED-PAYLOAD";

        let mut headers = HeaderMap::new();
        headers.insert(HOST, HeaderValue::from_static("127.0.0.1:61080"));
        headers.insert("x-amz-date", HeaderValue::from_static("20260424T120000Z"));
        headers.insert(
            "x-amz-content-sha256",
            HeaderValue::from_static(payload_hash),
        );
        headers.insert(
            CONTENT_LENGTH,
            HeaderValue::from_str(&content_length.to_string())
                .expect("content length should be valid"),
        );

        let mut signed_headers = vec![
            "content-length".to_string(),
            "host".to_string(),
            "x-amz-content-sha256".to_string(),
            "x-amz-date".to_string(),
        ];

        for (name, value) in extra_headers {
            let header_name =
                axum::http::HeaderName::from_bytes(name.as_bytes()).expect("header name is valid");
            headers.insert(
                header_name,
                HeaderValue::from_str(value).expect("extra header should be valid"),
            );
            signed_headers.push(name.to_ascii_lowercase());
        }

        signed_headers.sort();
        signed_headers.dedup();

        let canonical_request = format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            method.as_str(),
            canonical_uri(uri.path()),
            canonical_query_string(uri.query()),
            canonical_headers(&headers, &signed_headers)
                .expect("canonical headers should build in tests"),
            signed_headers.join(";"),
            payload_hash
        );

        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{}\n{}/{}/s3/aws4_request\n{}",
            amz_date,
            short_date,
            config.s3_region,
            sha256_hex(canonical_request.as_bytes())
        );

        let signature = sign_v4(
            &config.s3_secret_access_key,
            short_date,
            &config.s3_region,
            "s3",
            &string_to_sign,
        );
        let authorization = format!(
            "AWS4-HMAC-SHA256 Credential={}/{}/{}/s3/aws4_request, SignedHeaders={}, Signature={}",
            config.s3_access_key_id,
            short_date,
            config.s3_region,
            signed_headers.join(";"),
            signature
        );

        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&authorization).expect("authorization header should be valid"),
        );

        headers
    }

