    #[tokio::test]
    async fn control_api_key_middleware_accepts_header_bearer_cookie_and_query_bootstrap() {
        let mut state = test_state();
        Arc::make_mut(&mut state.config).control_api_key = Some("secret-admin-key".to_string());
        let app = Router::new()
            .route("/api/status", get(|| async { StatusCode::OK }))
            .route("/", get(|| async { StatusCode::OK }))
            .with_state(state.clone())
            .layer(middleware::from_fn_with_state(
                state,
                require_control_api_key,
            ));

        let x_api_key_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/api/status")
                    .header("x-api-key", "secret-admin-key")
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("x-api-key request should complete");
        assert_eq!(x_api_key_response.status(), StatusCode::OK);

        let bearer_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/api/status")
                    .header(AUTHORIZATION, "Bearer secret-admin-key")
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("bearer request should complete");
        assert_eq!(bearer_response.status(), StatusCode::OK);

        let cookie_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/api/status")
                    .header(COOKIE, "ccbg_admin_api_key=secret-admin-key")
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("cookie request should complete");
        assert_eq!(cookie_response.status(), StatusCode::OK);

        let query_response = app
            .oneshot(
                Request::builder()
                    .uri("/?api_key=secret-admin-key")
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("query request should complete");
        assert_eq!(query_response.status(), StatusCode::OK);
        assert_eq!(
            query_response
                .headers()
                .get(SET_COOKIE)
                .and_then(|value| value.to_str().ok()),
            Some("ccbg_admin_api_key=secret-admin-key; Path=/; HttpOnly; SameSite=Strict")
        );
    }

