    #[tokio::test]
    async fn capture_browser_flow_outputs_reads_script_values_and_url() {
        let state = test_state();
        let plan = browser_flow_plan(
            state.browser_flow_catalogs.as_ref(),
            "unicom",
            "pan.wo.cn-web",
            "unicom_sms_login",
            BTreeMap::from([
                (
                    "phone_number".to_string(),
                    serde_json::Value::String("18513581767".to_string()),
                ),
                (
                    "sms_code".to_string(),
                    serde_json::Value::String("288750".to_string()),
                ),
            ]),
            BTreeMap::new(),
        )
        .expect("login flow plan should bind");
        let reader = RecordingBrowserFlowOutputReader {
            values: Arc::new(Mutex::new(HashMap::from([
                (
                    "(() => { const listVm = document.querySelector('.file-list-container')?.__vue__ || document.querySelector('.file-list-container')?.__vueParentComponent?.proxy; return listVm?.$store?.state?.user?.token ?? null; })()".to_string(),
                    serde_json::Value::String("token-123".to_string()),
                ),
                (
                    "(() => sessionStorage.getItem('familyId') || null)()".to_string(),
                    serde_json::Value::String("family-42".to_string()),
                ),
                (
                    "(() => { const listVm = document.querySelector('.file-list-container')?.__vue__ || document.querySelector('.file-list-container')?.__vueParentComponent?.proxy; return listVm?.$store?.state?.user?.clientId ?? null; })()".to_string(),
                    serde_json::Value::String("1001000021".to_string()),
                ),
                (
                    "(() => { const listVm = document.querySelector('.file-list-container')?.__vue__ || document.querySelector('.file-list-container')?.__vueParentComponent?.proxy; const user = listVm?.$store?.state?.user || {}; const normalizeAbsolute = (value) => { if (value === null || value === undefined || value === '') { return null; } const raw = typeof value === 'string' ? value.trim() : value; if (raw === null || raw === undefined || raw === '') { return null; } if (typeof raw === 'number' && Number.isFinite(raw)) { if (raw > 1000000000000) { return Math.trunc(raw); } if (raw > 1000000000) { return Math.trunc(raw * 1000); } return null; } if (typeof raw === 'string') { if (/^\\d+$/.test(raw)) { return normalizeAbsolute(Number(raw)); } const parsed = Date.parse(raw); if (Number.isFinite(parsed)) { return Math.trunc(parsed); } } return null; }; for (const value of [user.sessionExpireTime, user.sessionExpiresAt, user.expireTime, user.expiresAt, user.tokenExpireTime, user.tokenExpiresAt]) { const normalized = normalizeAbsolute(value); if (normalized) { return normalized; } } for (const key of ['sessionExpireTime', 'sessionExpiresAt', 'expireTime', 'expiresAt', 'tokenExpireTime', 'tokenExpiresAt']) { const normalized = normalizeAbsolute(sessionStorage.getItem(key) || localStorage.getItem(key)); if (normalized) { return normalized; } } return null; })()".to_string(),
                    serde_json::Value::Number(serde_json::Number::from(1_778_920_000_000_u64)),
                ),
                (
                    "(() => { const listVm = document.querySelector('.file-list-container')?.__vue__ || document.querySelector('.file-list-container')?.__vueParentComponent?.proxy; const user = listVm?.$store?.state?.user || {}; const normalizeDuration = (value) => { if (value === null || value === undefined || value === '') { return null; } const raw = typeof value === 'string' ? value.trim() : value; if (raw === null || raw === undefined || raw === '') { return null; } const number = typeof raw === 'number' ? raw : (/^\\d+$/.test(raw) ? Number(raw) : NaN); if (!Number.isFinite(number) || number <= 0) { return null; } if (number <= 86400) { return Math.trunc(number * 1000); } if (number <= 31536000000) { return Math.trunc(number); } return null; }; for (const value of [user.sessionTimeoutMs, user.timeoutMs, user.tokenTimeoutMs, user.sessionTimeout, user.timeout, user.expiresIn, user.expireIn]) { const normalized = normalizeDuration(value); if (normalized) { return normalized; } } for (const key of ['sessionTimeoutMs', 'timeoutMs', 'tokenTimeoutMs', 'sessionTimeout', 'timeout', 'expiresIn', 'expireIn']) { const normalized = normalizeDuration(sessionStorage.getItem(key) || localStorage.getItem(key)); if (normalized) { return normalized; } } return null; })()".to_string(),
                    serde_json::Value::Number(serde_json::Number::from(7_200_000_u64)),
                ),
            ]))),
            request_headers: Arc::new(Mutex::new(HashMap::new())),
            request_fields: Arc::new(Mutex::new(HashMap::new())),
            current_url: Arc::new(Mutex::new(Some(
                "https://pan.wo.cn/pan/file_list/all".to_string(),
            ))),
        };

        let captured = capture_browser_flow_outputs(&plan, &reader)
            .await
            .expect("output capture should succeed");

        assert_eq!(
            captured.get("access_token"),
            Some(&serde_json::Value::String("token-123".to_string()))
        );
        assert_eq!(
            captured.get("family_id"),
            Some(&serde_json::Value::String("family-42".to_string()))
        );
        assert_eq!(
            captured.get("client_id"),
            Some(&serde_json::Value::String("1001000021".to_string()))
        );
        assert_eq!(
            captured.get("current_url"),
            Some(&serde_json::Value::String(
                "https://pan.wo.cn/pan/file_list/all".to_string()
            ))
        );
        assert_eq!(
            captured.get("session_expires_at_unix_ms"),
            Some(&serde_json::Value::Number(serde_json::Number::from(
                1_778_920_000_000_u64
            )))
        );
        assert_eq!(
            captured.get("session_timeout_ms"),
            Some(&serde_json::Value::Number(serde_json::Number::from(
                7_200_000_u64
            )))
        );
    }

