        assert_eq!(payload.rows[0].key, "docs/missing.txt");
        assert_eq!(payload.rows[0].home_object_state, "missing");
        assert!(payload.rows[0].delete_allowed);
        assert_eq!(payload.rows[1].key, "docs/existing.txt");
        assert_eq!(payload.rows[1].home_object_state, "exists");
        assert!(!payload.rows[1].delete_allowed);
        assert!(payload.rows.iter().all(|row| row.provider != "onedrive"));
