    #[test]
    fn provider_io_stats_track_rolling_and_large_transfer_throughput() {
        let stats = ProviderIoStatsState::new();
        stats.record_success_with_response(
            "mobile",
            ProviderIoOperationKind::Write,
            400,
            Some(120),
            Some(512 * 1024),
        );
        stats.record_success_with_response(
            "mobile",
            ProviderIoOperationKind::Write,
            2_000,
            Some(180),
            Some(16 * 1024 * 1024),
        );

        let snapshot = stats.snapshot_provider("mobile");
        let write = snapshot.write;
        assert_eq!(write.success_count, 2);
        assert_eq!(write.first_response_latency_ms, Some(120));
        assert_eq!(write.last_response_latency_ms, Some(180));
        assert_eq!(write.rolling_sample_count, 2);
        assert!(write.rolling_window_started_at_unix_ms.is_some());
        assert!(write.rolling_bytes_per_sec.is_some());
        assert_eq!(write.last_large_success_bytes, Some(16 * 1024 * 1024));
        assert!(write.last_large_success_bytes_per_sec.is_some());
        assert!(write.last_large_success_at_unix_ms.is_some());
    }

    #[test]
    fn provider_resource_stats_track_in_flight_spool_and_write_paths() {
        let stats = Arc::new(ProviderResourceStatsState::new());
        {
            let _read = stats.start_operation("mobile", ProviderResourceOperationKind::Read);
            let _write = stats.start_operation("mobile", ProviderResourceOperationKind::Write);
            let mut spool = stats.start_spool_tracking("mobile");
            spool.update_tracked_bytes(4096);
            stats.record_write_path("mobile", ProviderWritePathKind::Streaming);
            stats.record_write_path("mobile", ProviderWritePathKind::InMemory);
            stats.record_write_path("mobile", ProviderWritePathKind::Spooled);

            let snapshot = stats.snapshot_provider("mobile");
            assert_eq!(snapshot.read.in_flight, 1);
            assert_eq!(snapshot.read.peak_in_flight, 1);
            assert_eq!(snapshot.write.in_flight, 1);
            assert_eq!(snapshot.write.peak_in_flight, 1);
            assert_eq!(snapshot.spool.active_files, 1);
            assert_eq!(snapshot.spool.active_bytes, 4096);
            assert_eq!(snapshot.spool.peak_files, 1);
            assert_eq!(snapshot.spool.peak_bytes, 4096);
            assert_eq!(snapshot.write_paths.streaming_count, 1);
            assert_eq!(snapshot.write_paths.in_memory_count, 1);
            assert_eq!(snapshot.write_paths.spooled_count, 1);
        }

        let snapshot = stats.snapshot_provider("mobile");
        assert_eq!(snapshot.read.in_flight, 0);
        assert_eq!(snapshot.read.peak_in_flight, 1);
        assert_eq!(snapshot.write.in_flight, 0);
        assert_eq!(snapshot.write.peak_in_flight, 1);
        assert_eq!(snapshot.spool.active_files, 0);
        assert_eq!(snapshot.spool.active_bytes, 0);
        assert_eq!(snapshot.spool.peak_files, 1);
        assert_eq!(snapshot.spool.peak_bytes, 4096);
    }

