    #[tokio::test]
    async fn provider_limit_probe_emits_read_progress_events_for_long_reads() {
        let mut state = test_state();
        let backend = Arc::new(
            LimitProbeRecordingBackend::new(3, 100, 100, 3)
                .with_read_plan(3, Duration::from_millis(300)),
        );
        replace_backend(&mut state, ProviderId::Stub, backend);

        let (sender, mut receiver) = mpsc::unbounded_channel();
        let payload = execute_provider_limit_probe(
            state,
            "stub".to_string(),
            ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-progress-tests".to_string()),
                sizes: vec!["9B".to_string()],
                sizes_bytes: Vec::new(),
                read_back: true,
                delete_after: true,
                stop_after_first_success: false,
                chunk_size: Some("3B".to_string()),
                chunk_size_bytes: None,
                read_progress_interval_ms: Some(250),
                read_total_timeout_ms: Some(5_000),
            },
            Some(sender),
        )
        .await
        .expect("limit probe should complete");

        let mut progress_events = Vec::new();
        while let Some(event) = receiver.recv().await {
            if event.event == "read_progress" {
                progress_events.push(event);
            }
        }

        assert_eq!(payload.max_verified_upload_bytes, Some(9));
        assert_eq!(payload.max_verified_download_bytes, Some(9));
        assert!(!progress_events.is_empty());
        assert!(
            progress_events
                .iter()
                .any(|event| event.read_bytes.unwrap_or_default() > 0)
        );
    }

    #[tokio::test]
    async fn provider_limit_probe_times_out_long_read_back_and_keeps_partial_stats() {
        let mut state = test_state();
        let backend = Arc::new(
            LimitProbeRecordingBackend::new(3, 100, 100, 3)
                .with_read_plan(3, Duration::from_millis(450)),
        );
        replace_backend(&mut state, ProviderId::Stub, backend);

        let payload = run_provider_limit_probe(
            State(state),
            Path("stub".to_string()),
            Json(ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-timeout-tests".to_string()),
                sizes: vec!["9B".to_string()],
                sizes_bytes: Vec::new(),
                read_back: true,
                delete_after: true,
                stop_after_first_success: false,
                chunk_size: Some("3B".to_string()),
                chunk_size_bytes: None,
                read_progress_interval_ms: Some(250),
                read_total_timeout_ms: Some(1_100),
            }),
        )
        .await
        .expect("limit probe should finish with a read timeout result")
        .0;

        assert_eq!(payload.results.len(), 1);
        let step = &payload.results[0];
        assert!(step.upload_ok);
        assert_eq!(step.read_ok, Some(false));
        assert!(
            step.read_error
                .as_deref()
                .is_some_and(|message| message.contains("read-back exceeded total timeout"))
        );
        assert!(step.read_bytes.unwrap_or_default() > 0);
        assert!(step.read_bytes.unwrap_or_default() < step.size_bytes);
        assert!(step.read_elapsed_ms.unwrap_or_default() >= 1_100);
        assert_eq!(step.delete_ok, Some(true));
    }

    #[tokio::test]
    async fn provider_limit_probe_persists_latest_result_locally() {
        let mut state = test_state();
        let backend = Arc::new(LimitProbeRecordingBackend::new(4, 100, 100, 4));
        replace_backend(&mut state, ProviderId::Stub, backend);
        let payload = run_provider_limit_probe(
            State(state.clone()),
            Path("stub".to_string()),
            Json(ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-persist-tests".to_string()),
                sizes: vec!["8B".to_string()],
                sizes_bytes: Vec::new(),
                read_back: true,
                delete_after: true,
                stop_after_first_success: true,
                chunk_size: Some("4B".to_string()),
                chunk_size_bytes: None,
                read_progress_interval_ms: None,
                read_total_timeout_ms: None,
            }),
        )
        .await
        .expect("limit probe should complete")
        .0;

        let snapshot = control_plane_snapshot(&state);
        let persisted = snapshot
            .provider_limit_probes
            .get(&ProviderId::Stub)
            .expect("latest stub probe should persist");
        assert_eq!(persisted.checked_at_unix_ms, payload.checked_at_unix_ms);
        assert_eq!(persisted.max_verified_upload_bytes, Some(8));
        assert_eq!(persisted.max_verified_download_bytes, Some(8));
        assert_eq!(
            persisted.latency_semantics_version,
            PROVIDER_LIMIT_PROBE_LATENCY_SEMANTICS_VERSION_V2
        );
        let profile = snapshot
            .provider_limit_profiles
            .get(&ProviderId::Stub)
            .expect("stub limit profile should persist");
        assert_eq!(profile.max_verified_upload_bytes, Some(8));
        assert_eq!(profile.max_verified_download_bytes, Some(8));
        assert_eq!(profile.max_verified_upload_part_size_bytes, Some(4));
        assert!(profile.max_verified_upload_bytes_per_sec.is_some());
        assert!(profile.max_verified_download_bytes_per_sec.is_some());
        assert_eq!(
            profile.min_verified_upload_first_response_latency_ms,
            Some(1)
        );
        assert_eq!(
            profile.min_verified_download_first_response_latency_ms,
            Some(1)
        );
        assert_eq!(
            profile.max_verified_upload_checked_at_unix_ms,
            Some(payload.checked_at_unix_ms)
        );
        assert_eq!(
            profile.latency_semantics_version,
            PROVIDER_LIMIT_PROBE_LATENCY_SEMANTICS_VERSION_V2
        );
        let io = state.provider_io_stats.snapshot_provider("stub");
        assert_eq!(io.write.success_count, 1);
        assert_eq!(io.write.first_response_latency_ms, Some(1));
        assert_eq!(io.read.success_count, 1);
        assert_eq!(io.read.first_response_latency_ms, Some(1));

        let reloaded = load_control_plane_state(
            &state.config.control_plane_file,
            &state.config.credentials_dir,
            ControlPlaneState {
                topology: state.config.topology.clone(),
                high_speed_providers: Vec::new(),
                write_targets: vec![state.config.topology.primary_provider],
                applications: default_data_plane_applications(&state.config),
                encryption_profiles: Vec::new(),
                content_policies: Vec::new(),
                provider_limit_probes: BTreeMap::new(),
                provider_limit_profiles: BTreeMap::new(),
                object_placement_mode: ObjectPlacementMode::PreferPrimary,
                smb_sidecar: SmbSidecarConfig::from_env_defaults(),
                onedrive_policy: OnedrivePolicy::from_env_defaults(&state.config.topology),
                auth_capture_policy: AuthCapturePolicy::from_env_defaults(),
                suppressed_admin_alerts: Vec::new(),
                object_action_history: Vec::new(),
            },
            state.config.onedrive.enabled,
        )
        .expect("persisted control plane should load");
        assert_eq!(
            reloaded
                .provider_limit_probes
                .get(&ProviderId::Stub)
                .and_then(|probe| probe.max_verified_upload_bytes),
            Some(8)
        );
        assert_eq!(
            reloaded
                .provider_limit_profiles
                .get(&ProviderId::Stub)
                .and_then(|profile| profile.max_verified_upload_bytes),
            Some(8)
        );
        assert_eq!(
            reloaded
                .provider_limit_profiles
                .get(&ProviderId::Stub)
                .map(|profile| profile.latest_probe_hit_daily_flow_limit),
            Some(false)
        );
    }

