    async fn encryption_profiles_cannot_remove_profiles_still_referenced_by_content_policies() {
        let state = test_state();
        let _ = update_encryption_profiles(
            State(state.clone()),
            Json(EncryptionProfilesInput {
                profiles: vec![EncryptionProfileInput {
                    id: "router-default".to_string(),
                    label: Some("Router default".to_string()),
                    enabled: true,
                    algorithm_preference: EncryptionAlgorithmPreference::Auto,
                    chunk_plaintext_bytes: 1024 * 1024,
                    key_id: "kek-2026-01".to_string(),
                    key_source_kind: EncryptionKeySourceKind::EnvVar,
                    key_source_ref: "CCBG_ENCRYPTION_KEY_ROUTER_DEFAULT".to_string(),
                    notes: None,
                }],
            }),
        )
        .await
        .expect("initial encryption profile update should succeed");
        let _ = update_content_policies(
            State(state.clone()),
            Json(ContentPoliciesInput {
                policies: vec![ContentPolicyRule {
                    id: "encrypt-large".to_string(),
                    label: Some("Encrypt large writes".to_string()),
                    enabled: true,
                    application_ids: vec!["enc-app".to_string()],
                    buckets: vec!["root".to_string()],
                    prefixes: vec!["videos/".to_string()],
                    content_types: vec!["video/*".to_string()],
                    encryption_profile_id: Some("router-default".to_string()),
                    sync_targets: Vec::new(),
                    fallback_read_order: Vec::new(),
                }],
            }),
        )
        .await
        .expect("content policy should bind to the known profile");

        let ApiError(error) = update_encryption_profiles(
            State(state.clone()),
            Json(EncryptionProfilesInput {
                profiles: Vec::new(),
            }),
        )
        .await
        .expect_err("removing a profile referenced by a content policy should fail");
        let message = error.to_string();
        assert!(message.contains("encrypt-large"));
        assert!(message.contains("router-default"));
    }

    #[tokio::test]
    async fn content_policy_encryption_profile_applies_only_to_matching_writes() {
        let state = test_state();
        install_test_managed_encryption_profiles_for_application(
            &state,
            "enc-app",
            "enc-access",
            "enc-secret",
            "managed-test-key",
            &[("video-large", 256 * 1024)],
        );

        let _ = update_content_policies(
            State(state.clone()),
            Json(ContentPoliciesInput {
                policies: vec![ContentPolicyRule {
                    id: "video-large-rule".to_string(),
                    label: Some("Video large override".to_string()),
                    enabled: true,
                    application_ids: vec!["enc-app".to_string()],
                    buckets: vec!["root".to_string()],
                    prefixes: vec!["videos/".to_string()],
                    content_types: vec!["video/*".to_string()],
                    encryption_profile_id: Some("video-large".to_string()),
                    sync_targets: Vec::new(),
                    fallback_read_order: Vec::new(),
                }],
            }),
        )
        .await
        .expect("content policy should save");

        let matched_bucket = "root".to_string();
        let matched_key = "videos/clip.mp4".to_string();
        let matched_body = Bytes::from_static(b"video payload");
        let matched_uri: Uri = format!("/{matched_bucket}/{matched_key}")
            .parse()
            .expect("uri should parse");
        let matched_headers = signed_headers_for_application(
            &state.config,
            "enc-access",
            "enc-secret",
            &Method::PUT,
            &matched_uri,
            &matched_body,
            &[("content-type", "video/mp4")],
        );
        put_object(
            State(state.clone()),
            Path((matched_bucket.clone(), matched_key.clone())),
            Method::PUT,
            OriginalUri(matched_uri),
            matched_headers,
            matched_body.into(),
        )
        .await
        .expect("policy-matched encrypted put should succeed");

        let matched_logical = load_logical_object_record(&state, &matched_bucket, &matched_key)
            .expect("logical metadata should load")
            .expect("logical metadata should exist");
        assert_eq!(
            matched_logical.encryption_profile_id.as_deref(),
            Some("video-large")
        );
        assert_eq!(matched_logical.chunk_plaintext_bytes, Some(256 * 1024));

        let unmatched_bucket = "root".to_string();
        let unmatched_key = "docs/readme.txt".to_string();
        let unmatched_body = Bytes::from_static(b"plain text payload");
        let unmatched_uri: Uri = format!("/{unmatched_bucket}/{unmatched_key}")
            .parse()
            .expect("uri should parse");
        let unmatched_headers = signed_headers_for_application(
            &state.config,
            "enc-access",
            "enc-secret",
            &Method::PUT,
            &unmatched_uri,
            &unmatched_body,
            &[("content-type", "text/plain")],
        );
        put_object(
            State(state.clone()),
            Path((unmatched_bucket.clone(), unmatched_key.clone())),
            Method::PUT,
            OriginalUri(unmatched_uri),
            unmatched_headers,
            unmatched_body.into(),
        )
        .await
        .expect("unmatched plaintext put should succeed");

        let unmatched_logical =
            load_logical_object_record(&state, &unmatched_bucket, &unmatched_key)
                .expect("logical metadata should load");
        assert!(unmatched_logical.is_none());
    }

    #[tokio::test]
    async fn data_plane_applications_drive_s3_signature_authentication() {
        let state = test_state();
        let uri: Uri = "/root/application-auth.txt"
            .parse()
            .expect("uri should parse");
        let headers = signed_headers_for_application(
            &state.config,
            "app-access",
            "app-secret",
            &Method::GET,
            &uri,
            &[],
            &[],
        );

        assert!(authorize_s3(&state, &Method::GET, &uri, &headers, None).is_err());

        let payload = update_data_plane_applications(
            State(state.clone()),
            Json(DataPlaneApplicationsInput {
                applications: vec![
                    DataPlaneApplicationInput {
                        id: "app-a".to_string(),
                        label: Some("Application A".to_string()),
                        access_key_id: "app-access".to_string(),
                        secret_access_key: Some("app-secret".to_string()),
                        enabled: true,
                        permissions: None,
                    },
                    DataPlaneApplicationInput {
                        id: "disabled-app".to_string(),
                        label: None,
                        access_key_id: "disabled-access".to_string(),
                        secret_access_key: Some("disabled-secret".to_string()),
                        enabled: false,
                        permissions: None,
                    },
                ],
            }),
        )
        .await
        .expect("applications should update")
        .0;
        assert_eq!(payload.len(), 2);
        assert!(payload.iter().all(|entry| entry.secret_access_key_present));

        let identity = authorize_s3(&state, &Method::GET, &uri, &headers, None)
            .expect("enabled application should authenticate");
        assert_eq!(identity.application_id, "app-a");
        assert_eq!(identity.access_key_id, "app-access");

        let payload = update_data_plane_applications(
            State(state.clone()),
            Json(DataPlaneApplicationsInput {
                applications: vec![DataPlaneApplicationInput {
                    id: "app-a".to_string(),
                    label: Some("Application A renamed".to_string()),
                    access_key_id: "app-access".to_string(),
                    secret_access_key: None,
                    enabled: true,
                    permissions: None,
                }],
            }),
        )
        .await
        .expect("application update should preserve blank existing secret")
        .0;
        assert_eq!(payload.len(), 1);
        let identity = authorize_s3(&state, &Method::GET, &uri, &headers, None)
            .expect("blank admin update should preserve existing application secret");
        assert_eq!(identity.application_id, "app-a");

        let disabled_headers = signed_headers_for_application(
            &state.config,
            "disabled-access",
            "disabled-secret",
            &Method::GET,
            &uri,
            &[],
            &[],
        );
        assert!(authorize_s3(&state, &Method::GET, &uri, &disabled_headers, None).is_err());
    }

    #[tokio::test]
    async fn data_plane_application_permissions_restrict_s3_actions_and_scope() {
        let state = test_state();
        let payload = update_data_plane_applications(
            State(state.clone()),
            Json(DataPlaneApplicationsInput {
                applications: vec![DataPlaneApplicationInput {
                    id: "scoped-app".to_string(),
                    label: Some("Scoped app".to_string()),
                    access_key_id: "scoped-access".to_string(),
                    secret_access_key: Some("scoped-secret".to_string()),
                    enabled: true,
                    permissions: Some(DataPlaneApplicationPermissionsInput {
                        list_buckets: true,
                        list_objects: true,
                        read_object: true,
                        write_object: true,
                        delete_object: false,
                        allowed_buckets: vec!["root".to_string()],
                        allowed_prefixes: vec!["allowed/".to_string()],
                    }),
                }],
            }),
        )
        .await
        .expect("applications should update")
        .0;
        assert_eq!(payload.len(), 1);
        assert!(!payload[0].permissions.delete_object);
        assert_eq!(payload[0].permissions.allowed_buckets, vec!["root"]);
        assert_eq!(payload[0].permissions.allowed_prefixes, vec!["allowed"]);

        let allowed_uri: Uri = "/root/allowed/file.txt".parse().expect("uri should parse");
        let allowed_headers = signed_headers_for_application(
            &state.config,
            "scoped-access",
            "scoped-secret",
            &Method::GET,
            &allowed_uri,
            &[],
            &[],
        );
        let identity = authorize_s3(&state, &Method::GET, &allowed_uri, &allowed_headers, None)
            .expect("application should authenticate");
        ensure_s3_application_permission(
            &identity,
            S3ActionKind::ReadObject,
            Some("root"),
            Some("allowed/file.txt"),
        )
        .expect("read should be allowed inside prefix");

        let denied_delete = ensure_s3_application_permission(
            &identity,
            S3ActionKind::DeleteObject,
            Some("root"),
            Some("allowed/file.txt"),
        )
        .expect_err("delete should be denied");
        assert_eq!(denied_delete.status, StatusCode::FORBIDDEN);
        assert!(denied_delete.message.contains("not allowed"));

        let denied_prefix = ensure_s3_application_permission(
            &identity,
            S3ActionKind::ReadObject,
            Some("root"),
            Some("other/file.txt"),
        )
        .expect_err("reads outside the allowed prefix should fail");
        assert_eq!(denied_prefix.status, StatusCode::FORBIDDEN);
        assert!(denied_prefix.message.contains("not allowed"));

        let denied_parent_key = ensure_s3_application_permission(
            &identity,
            S3ActionKind::ReadObject,
            Some("root"),
            Some("allowed2/file.txt"),
        )
        .expect_err("direct object reads must not match adjacent prefixes");
        assert_eq!(denied_parent_key.status, StatusCode::FORBIDDEN);

        ensure_s3_application_permission(
            &identity,
            S3ActionKind::ListObjects,
            Some("root"),
            Some("allowed"),
        )
        .expect("list prefix should be allowed when it can contain allowed objects");

        let denied_bucket = ensure_s3_application_permission(
            &identity,
            S3ActionKind::ListObjects,
            Some("family"),
            Some("allowed/file.txt"),
        )
        .expect_err("list should be denied outside the allowed bucket");
        assert_eq!(denied_bucket.status, StatusCode::FORBIDDEN);
        assert!(denied_bucket.message.contains("not allowed"));
    }

    #[tokio::test]
    async fn list_results_are_filtered_by_application_permissions() {
        let state = test_state();
        let _ = update_data_plane_applications(
            State(state.clone()),
            Json(DataPlaneApplicationsInput {
                applications: vec![DataPlaneApplicationInput {
                    id: "scoped-list-app".to_string(),
                    label: Some("Scoped list app".to_string()),
                    access_key_id: "scoped-list-access".to_string(),
                    secret_access_key: Some("scoped-list-secret".to_string()),
                    enabled: true,
                    permissions: Some(DataPlaneApplicationPermissionsInput {
                        list_buckets: true,
                        list_objects: true,
                        read_object: true,
                        write_object: true,
                        delete_object: true,
                        allowed_buckets: vec!["root".to_string()],
                        allowed_prefixes: vec!["allowed/".to_string()],
                    }),
                }],
            }),
        )
        .await
        .expect("applications should update");

        let stub_backend = backend_for_provider(&state, ProviderId::Stub).expect("stub backend");
        stub_backend
            .put_object(PutObjectRequest {
                container: "root".to_string(),
                key: "allowed/a.txt".to_string(),
                body: Bytes::from_static(b"a").into(),
                size: Some(1),
                content_type: None,
                preferred_upload_part_size_bytes: None,
            })
            .await
            .expect("seed allowed object");
        stub_backend
            .put_object(PutObjectRequest {
                container: "root".to_string(),
                key: "blocked/b.txt".to_string(),
                body: Bytes::from_static(b"b").into(),
                size: Some(1),
                content_type: None,
                preferred_upload_part_size_bytes: None,
            })
            .await
            .expect("seed blocked object");

        let bucket_uri: Uri = "/".parse().expect("uri should parse");
        let bucket_headers = signed_headers_for_application(
            &state.config,
            "scoped-list-access",
            "scoped-list-secret",
            &Method::GET,
            &bucket_uri,
            &[],
            &[],
        );
        let bucket_response = list_buckets(
            State(state.clone()),
            Method::GET,
            OriginalUri(bucket_uri),
            bucket_headers,
        )
        .await
        .expect("list buckets should succeed");
        let bucket_body = to_bytes(bucket_response.into_body(), usize::MAX)
            .await
            .expect("response body should read");
        let bucket_xml = String::from_utf8(bucket_body.to_vec()).expect("xml should be utf-8");
        assert!(bucket_xml.contains("<Name>root</Name>"));
        assert!(!bucket_xml.contains("<Name>family</Name>"));

        let list_uri: Uri = "/root?list-type=2".parse().expect("uri should parse");
        let list_headers = signed_headers_for_application(
            &state.config,
            "scoped-list-access",
            "scoped-list-secret",
            &Method::GET,
            &list_uri,
            &[],
            &[],
        );
        let list_response = list_objects_v2(
            State(state.clone()),
            Path("root".to_string()),
            Query(ListObjectsV2Query {
                list_type: Some("2".to_string()),
                prefix: None,
                max_keys: None,
                delimiter: None,
                continuation_token: None,
            }),
            Method::GET,
            OriginalUri(list_uri),
            list_headers,
        )
        .await
        .expect("list objects should succeed");
        let list_body = to_bytes(list_response.into_body(), usize::MAX)
            .await
            .expect("response body should read");
        let list_xml = String::from_utf8(list_body.to_vec()).expect("xml should be utf-8");
        assert!(list_xml.contains("<Key>allowed/a.txt</Key>"));
        assert!(!list_xml.contains("<Key>blocked/b.txt</Key>"));
    }

    #[tokio::test]
    async fn content_policy_overrides_replication_targets_for_matching_application_content() {
        let state = test_state();
        let _ = update_content_policies(
            State(state.clone()),
            Json(ContentPoliciesInput {
                policies: vec![ContentPolicyRule {
                    id: "large-video".to_string(),
                    label: Some("Large video".to_string()),
                    enabled: true,
                    application_ids: vec!["app-a".to_string()],
                    buckets: vec!["root".to_string()],
                    prefixes: vec!["videos".to_string()],
                    content_types: vec!["video/*".to_string()],
                    encryption_profile_id: None,
                    sync_targets: vec![ProviderId::Telecom, ProviderId::Mobile],
                    fallback_read_order: vec![ProviderId::Mobile],
                }],
            }),
        )
        .await
        .expect("content policies should update");

        let app_a = S3ApplicationIdentity {
            application_id: "app-a".to_string(),
            access_key_id: "app-access".to_string(),
            permissions: DataPlaneApplicationPermissions::default(),
        };
        let matched = effective_topology_for_replication_put(
            &state,
            Some(&app_a),
            "root",
            "videos/clip.mp4",
            1024,
            Some("video/mp4"),
        )
        .await
        .expect("matching policy topology should resolve");
        assert_eq!(
            matched.sync_targets,
            vec![ProviderId::Telecom, ProviderId::Mobile]
        );
        assert_eq!(matched.fallback_read_order, vec![ProviderId::Mobile]);

        let other_app = S3ApplicationIdentity {
            application_id: "app-b".to_string(),
            access_key_id: "other-access".to_string(),
            permissions: DataPlaneApplicationPermissions::default(),
        };
        let unmatched = effective_topology_for_replication_put(
            &state,
            Some(&other_app),
            "root",
            "videos/clip.mp4",
            1024,
            Some("video/mp4"),
        )
        .await
        .expect("unmatched policy topology should resolve");
        assert_eq!(unmatched.sync_targets, vec![ProviderId::Onedrive]);
        assert_eq!(unmatched.fallback_read_order, vec![ProviderId::Onedrive]);
    }

    #[tokio::test]
